"use server";

// Every dashboard mutation. Each one: requireTruckAccess() for the truck
// (never an ID from the browser) → Zod-validate the input → a lib/tenant.ts
// function that scopes the write to that truck.

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { z } from "zod";
import { DEMO_JOIN_ALLOWED, getUserEmail, getUserId } from "@/lib/dev-auth";
import {
  advanceOrderStatus,
  cancelOrder,
  createMenuItem,
  createSection,
  createTruckForUser,
  getOrderStatus,
  isSlugTaken,
  joinDemoTruck,
  requireTruckAccess,
  setItemArchived,
  setItemAvailability,
  updateMenuItem,
  userHasTruck,
} from "@/lib/tenant";
import { NEXT_STATUS } from "@/lib/orders/status";
import { parseDollarsToCents } from "@/lib/money";
import { slugSchema } from "@/lib/slug";

export type ActionResult = { ok: true } | { ok: false; error: string };

const id = z.string().min(1).max(50);
const fail = (error: string): ActionResult => ({ ok: false, error });

function refresh(truckSlug: string) {
  revalidatePath("/dashboard", "layout");
  revalidatePath(`/${truckSlug}`, "layout");
}

// ─── Orders ────────────────────────────────────────────────────────────────

const advanceSchema = z.object({ orderId: id, from: z.enum(["PAID", "ACCEPTED", "PREPARING", "READY"]) });

export async function advanceOrder(input: z.input<typeof advanceSchema>): Promise<ActionResult> {
  const { truck } = await requireTruckAccess();
  const parsed = advanceSchema.safeParse(input);
  if (!parsed.success) return fail("That order can't be updated.");
  const { orderId, from } = parsed.data;

  const to = NEXT_STATUS[from];
  const moved = await advanceOrderStatus(truck.id, orderId, from, to);
  refresh(truck.slug);
  if (moved) return { ok: true };
  // The 30-minute sweep (or another tab) may have already put it there.
  if ((await getOrderStatus(truck.id, orderId)) === to) return { ok: true };
  return fail("This order was already updated. The queue has been refreshed.");
}

export async function cancelOrderAction(orderId: string): Promise<ActionResult> {
  const { truck } = await requireTruckAccess();
  if (!id.safeParse(orderId).success) return fail("That order can't be cancelled.");

  // TODO(Stream C): refund the payment through Stripe as part of cancelling.
  const cancelled = await cancelOrder(truck.id, orderId);
  refresh(truck.slug);
  return cancelled ? { ok: true } : fail("This order can't be cancelled anymore.");
}

// ─── Stock & menu ──────────────────────────────────────────────────────────

export async function setStock(input: { itemId: string; isAvailable: boolean }): Promise<ActionResult> {
  const { truck } = await requireTruckAccess();
  const parsed = z.object({ itemId: id, isAvailable: z.boolean() }).safeParse(input);
  if (!parsed.success) return fail("That item can't be updated.");

  const updated = await setItemAvailability(truck.id, parsed.data.itemId, parsed.data.isAvailable);
  refresh(truck.slug);
  return updated ? { ok: true } : fail("That item no longer exists.");
}

const itemSchema = z.object({
  itemId: id.optional(),
  sectionId: id,
  name: z.string().trim().min(1, "Give the item a name.").max(80, "Keep the name under 80 characters."),
  description: z.string().trim().max(300, "Keep the description under 300 characters."),
  price: z.string().max(20),
  // Only a URL this app issued. /api/uploads returns /api/photos/<id>; anything
  // else means the value didn't come from our upload route.
  imageUrl: z
    .string()
    .regex(/^\/api\/photos\/[a-z0-9]{1,40}$/)
    .nullable(),
  isAvailable: z.boolean(),
});

export type SaveItemResult = ActionResult | { ok: false; error: string; field: "name" | "description" | "price" };

export async function saveMenuItem(input: z.input<typeof itemSchema>): Promise<SaveItemResult> {
  const { truck } = await requireTruckAccess();
  const parsed = itemSchema.safeParse(input);
  if (!parsed.success) {
    const issue = parsed.error.issues[0];
    const field = issue?.path[0];
    return field === "name" || field === "description"
      ? { ok: false, error: issue.message, field }
      : fail("Check the item's details and try again.");
  }

  const priceCents = parseDollarsToCents(parsed.data.price);
  if (priceCents === null || priceCents > 100_000) {
    return { ok: false, error: "Enter a price like 12.50.", field: "price" };
  }

  const { itemId, sectionId, name, description, imageUrl, isAvailable } = parsed.data;
  const data = { sectionId, name, description, imageUrl, isAvailable, priceCents };
  const saved = itemId ? await updateMenuItem(truck.id, itemId, data) : await createMenuItem(truck.id, data);
  refresh(truck.slug);
  return saved ? { ok: true } : fail("That section or item no longer exists.");
}

export async function setArchived(input: { itemId: string; archived: boolean }): Promise<ActionResult> {
  const { truck } = await requireTruckAccess();
  const parsed = z.object({ itemId: id, archived: z.boolean() }).safeParse(input);
  if (!parsed.success) return fail("That item can't be updated.");

  const updated = await setItemArchived(truck.id, parsed.data.itemId, parsed.data.archived);
  refresh(truck.slug);
  return updated ? { ok: true } : fail("That item no longer exists.");
}

export async function addSection(name: string): Promise<ActionResult> {
  const { truck } = await requireTruckAccess();
  const parsed = z.string().trim().min(1, "Give the section a name.").max(40).safeParse(name);
  if (!parsed.success) return fail(parsed.error.issues[0].message);

  const created = await createSection(truck.id, parsed.data);
  refresh(truck.slug);
  return created ? { ok: true } : fail("Your truck doesn't have a menu yet.");
}

// ─── Onboarding ────────────────────────────────────────────────────────────

const truckSchema = z.object({
  name: z.string().trim().min(1, "Enter your truck's name.").max(60),
  slug: slugSchema,
  timezone: z.string().refine((tz) => Intl.supportedValuesOf("timeZone").includes(tz), "Pick a timezone."),
});

export type CreateTruckResult = { ok: false; error: string; field?: "name" | "slug" | "timezone" };

export async function createTruck(input: z.input<typeof truckSchema>): Promise<CreateTruckResult> {
  const userId = await getUserId();
  if (!userId) redirect("/sign-in");
  if (await userHasTruck(userId)) redirect("/dashboard");

  const parsed = truckSchema.safeParse(input);
  if (!parsed.success) {
    const issue = parsed.error.issues[0];
    const field = issue.path[0] as "name" | "slug" | "timezone";
    return { ok: false, error: issue.message, field };
  }
  if (await isSlugTaken(parsed.data.slug)) {
    return { ok: false, error: "That address is taken. Try another.", field: "slug" };
  }

  await createTruckForUser(userId, { ...parsed.data, notificationEmail: await getUserEmail() });
  redirect("/dashboard");
}

export async function joinDemo(): Promise<CreateTruckResult> {
  const userId = await getUserId();
  if (!userId) redirect("/sign-in");
  if (!DEMO_JOIN_ALLOWED) return { ok: false, error: "The demo truck isn't available here." };

  const joined = await joinDemoTruck(userId, await getUserEmail());
  if (!joined) return { ok: false, error: "The demo truck hasn't been seeded. Run: npx prisma db seed" };
  redirect("/dashboard");
}

"use server";

import { redirect } from "next/navigation";
import { getUserEmail, getUserId } from "@/lib/dev-auth";
import { isWellFormedToken } from "@/lib/invites";
import { acceptInvite } from "@/lib/tenant";

// Public on purpose (the invitee isn't on the truck yet), so it has no
// requireTruckAccess(). The token is the credential, acceptInvite re-checks it
// inside a transaction, and every outcome ends in a redirect: the page then
// shows whichever state the invite is really in.
export async function acceptInviteAction(formData: FormData): Promise<void> {
  const token = String(formData.get("token") ?? "");
  if (!isWellFormedToken(token)) redirect("/");

  const userId = await getUserId();
  if (!userId) redirect(`/sign-in?redirect_url=${encodeURIComponent(`/invite/${token}`)}`);

  const result = await acceptInvite(token, userId, await getUserEmail(), new Date());
  redirect(result.status === "joined" || result.status === "already_member" ? "/dashboard" : `/invite/${token}`);
}

import Link from "next/link";
import { redirect } from "next/navigation";
import { AuthShell } from "@/components/platform/auth-shell";
import { Button, buttonVariants } from "@/components/ui/button";
import { getUserId } from "@/lib/dev-auth";
import { isWellFormedToken } from "@/lib/invites";
import { getInviteByToken, getMembership } from "@/lib/tenant";
import { acceptInviteAction } from "./actions";

// The token is a credential: keep it out of search indexes and Referer headers.
export const metadata = { title: "Team invite", robots: { index: false, follow: false }, referrer: "no-referrer" as const };

// Dead links say nothing about which truck they were for.
const DEAD: Record<string, { title: string; body: string }> = {
  unknown: { title: "This invite link isn't valid", body: "Check that you copied the whole link, or ask the truck owner for a new invite." },
  expired: { title: "This invite has expired", body: "Invites work for 7 days. Ask the truck owner to send you a new one." },
  accepted: { title: "This invite was already used", body: "If that was you, sign in to open the dashboard. Otherwise ask the owner for a new invite." },
  revoked: { title: "This invite was cancelled", body: "The truck owner withdrew it. Ask them if you think that's a mistake." },
};

export default async function InvitePage({ params }: { params: Promise<{ token: string }> }) {
  const { token } = await params;
  const invite = isWellFormedToken(token) ? await getInviteByToken(token, new Date()) : null;

  const dead = !invite ? DEAD.unknown : invite.state === "valid" ? null : DEAD[invite.state];
  if (dead) {
    return (
      <Card title={dead.title}>
        <p className="mt-2 text-muted-foreground">{dead.body}</p>
        <LinkButton href="/dashboard">Go to the dashboard</LinkButton>
      </Card>
    );
  }
  if (!invite) return null; // unreachable: `dead` covers it; narrows the type

  const userId = await getUserId();
  // Signed out: sign in (or up), then Clerk sends them straight back here.
  if (!userId) redirect(`/sign-in?redirect_url=${encodeURIComponent(`/invite/${token}`)}`);

  if (invite.truckId && (await getMembership(invite.truckId, userId))) {
    return (
      <Card title={`You're already on ${invite.truckName}`}>
        <p className="mt-2 text-muted-foreground">This invite isn&apos;t needed. You can already open the dashboard.</p>
        <LinkButton href="/dashboard">Open the dashboard</LinkButton>
      </Card>
    );
  }

  return (
    <Card title={`Join ${invite.truckName}`}>
      <p className="mt-2 text-muted-foreground">You&apos;ve been invited as {invite.role === "OWNER" ? "an owner" : "staff"}.</p>
      <form action={acceptInviteAction} className="mt-6">
        <input type="hidden" name="token" value={token} />
        <Button type="submit" className="h-12 rounded-xl px-6 text-base font-semibold">
          Accept invite
        </Button>
      </form>
    </Card>
  );
}

function Card({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <AuthShell>
      <section className="w-full max-w-md rounded-2xl bg-surface p-6">
        <h1 className="text-[1.75rem] leading-tight font-semibold tracking-[-0.03em]">{title}</h1>
        {children}
      </section>
    </AuthShell>
  );
}

function LinkButton({ href, children }: { href: string; children: React.ReactNode }) {
  return (
    <Link href={href} className={`${buttonVariants()} mt-6 h-12 rounded-xl px-6 text-base font-semibold`}>
      {children}
    </Link>
  );
}

"use server";

import { z } from "zod";
import { getTruckFromRequest } from "@/lib/tenant";
import { createOrder } from "@/lib/orders/createOrder";
import { markOrderPaid } from "@/lib/orders/markOrderPaid";
import { MAX_QUANTITY_PER_LINE, MAX_TIP_BPS } from "@/lib/pricing";

// Only IDs, quantities, and the customer's details come from the browser.
// Every price is recomputed in lib/pricing.ts.
const placeOrderSchema = z.object({
  truckSlug: z.string().min(1).max(100),
  serviceId: z.string().min(1).max(50),
  pickupSlotId: z.string().min(1).max(50),
  tipBps: z.number().int().min(0).max(MAX_TIP_BPS),
  customerName: z.string().trim().min(1, "Enter a name for the order.").max(60),
  customerPhone: z
    .string()
    .trim()
    .max(30)
    .refine((p) => p.replace(/\D/g, "").length >= 10, "Enter a phone number with area code."),
  lines: z
    .array(
      z.object({
        menuItemId: z.string().min(1).max(50),
        optionIds: z.array(z.string().min(1).max(50)).max(20),
        quantity: z.number().int().min(1).max(MAX_QUANTITY_PER_LINE),
      })
    )
    .min(1, "Your order is empty.")
    .max(50),
});

export type PlaceOrderResult = { ok: true; orderId: string } | { ok: false; error: string };

export async function placeOrder(input: z.input<typeof placeOrderSchema>): Promise<PlaceOrderResult> {
  const parsed = placeOrderSchema.safeParse(input);
  if (!parsed.success) return { ok: false, error: parsed.error.issues[0]?.message ?? "Check your order and try again." };
  const { truckSlug, ...order } = parsed.data;

  const truck = await getTruckFromRequest(truckSlug);
  if (!truck) return { ok: false, error: "This truck doesn't exist." };

  const result = await createOrder({ ...order, truckId: truck.id, source: "WEB" });
  if (!result.ok) return result;

  // TODO(Stream C): redirect to Stripe Checkout here instead. The Stripe
  // webhook then calls markOrderPaid. For now the order is treated as paid.
  await markOrderPaid(truck.id, result.orderId);

  return { ok: true, orderId: result.orderId };
}

import { notFound } from "next/navigation";
import { getBookableSlots, getStorefrontMenu, getTruckFromRequest, getUpcomingServices } from "@/lib/tenant";
import { cartStorageKey } from "@/lib/cart";
import { orderingWindow, pickDefaultService } from "@/lib/service";
import { formatWhen } from "@/lib/time";
import { AddedNotice } from "@/components/storefront/added-notice";
import { CartProvider } from "@/components/storefront/cart-provider";
import { MenuList } from "@/components/storefront/menu-list";
import { OrderBar } from "@/components/storefront/order-bar";
import { ServiceHero } from "@/components/storefront/service-hero";
import { StorefrontFooter } from "@/components/storefront/storefront-footer";
import { UpcomingServices } from "@/components/storefront/upcoming-services";

// Depends on the current time (what's open, which slots remain), so never prerender.
export const dynamic = "force-dynamic";

type Props = {
  params: Promise<{ truckSlug: string }>;
  searchParams: Promise<{ service?: string }>;
};

export default async function StorefrontPage({ params, searchParams }: Props) {
  const { truckSlug } = await params;
  const { service: serviceParam } = await searchParams;

  const truck = await getTruckFromRequest(truckSlug);
  if (!truck) notFound();

  const now = new Date();
  const { services, locations } = await getUpcomingServices(truck.id, now);
  const selected = services.find((s) => s.id === serviceParam) ?? pickDefaultService(services, now);

  if (!selected) {
    return (
      <main className="mx-auto max-w-2xl px-4 py-16">
        <h1 className="font-display text-4xl font-bold">{truck.name}</h1>
        <p className="mt-3 text-muted-foreground">
          No upcoming stops are scheduled yet. Check back soon to see where the truck will be next.
        </p>
      </main>
    );
  }

  const [menu, slots] = await Promise.all([
    getStorefrontMenu(truck.id, selected.menuId),
    getBookableSlots(truck.id, selected.id, now),
  ]);
  if (!menu) notFound();

  const ordering = orderingWindow(selected, now);
  const closedReason =
    ordering === "not-yet"
      ? `Preorders for this stop open ${formatWhen(selected.orderingOpensAt, truck.timezone, now)}.`
      : ordering === "closed"
        ? "Online ordering has closed for this stop."
        : null;

  return (
    <CartProvider storageKey={cartStorageKey(truck.slug, selected.id)}>
      <main className="pb-28">
        <ServiceHero
          truck={truck}
          service={selected}
          location={locations[selected.locationId]}
          firstSlot={slots[0]}
          now={now}
        />
        <UpcomingServices
          truck={truck}
          services={services}
          locations={locations}
          selectedId={selected.id}
          now={now}
        />
        <MenuList menu={menu} canOrder={ordering === "open"} closedReason={closedReason} />
        <StorefrontFooter truck={truck} />
      </main>
      <AddedNotice menu={menu} />
      <OrderBar menu={menu} checkoutHref={`/${truck.slug}/checkout?service=${selected.id}`} />
    </CartProvider>
  );
}

"use client";

import { useState, useTransition } from "react";
import type { ManagedItem, ManagedSection } from "@/lib/types";
import { centsToInput } from "@/lib/money";
import { saveMenuItem, type SaveItemResult } from "@/app/(dashboard)/dashboard/actions";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Sheet, SheetContent, SheetDescription, SheetTitle } from "@/components/ui/sheet";
import { PhotoField } from "@/components/dashboard/photo-field";

type Props = {
  editing: { item: ManagedItem | null; sectionId: string } | null;
  sections: ManagedSection[];
  onClose: () => void;
};

export function ItemFormSheet({ editing, sections, onClose }: Props) {
  return (
    <Sheet open={editing !== null} onOpenChange={(open) => !open && onClose()}>
      <SheetContent side="right" className="w-full gap-0 overflow-y-auto bg-surface p-0 sm:max-w-md">
        {editing && (
          <ItemForm
            key={editing.item?.id ?? `new-${editing.sectionId}`}
            item={editing.item}
            defaultSectionId={editing.sectionId}
            sections={sections}
            onSaved={onClose}
          />
        )}
      </SheetContent>
    </Sheet>
  );
}

function ItemForm({
  item,
  defaultSectionId,
  sections,
  onSaved,
}: {
  item: ManagedItem | null;
  defaultSectionId: string;
  sections: ManagedSection[];
  onSaved: () => void;
}) {
  const [name, setName] = useState(item?.name ?? "");
  const [description, setDescription] = useState(item?.description ?? "");
  const [price, setPrice] = useState(item ? centsToInput(item.priceCents) : "");
  const [imageUrl, setImageUrl] = useState<string | null>(item?.imageUrl ?? null);
  const [sectionId, setSectionId] = useState(defaultSectionId);
  const [isAvailable, setIsAvailable] = useState(item?.isAvailable ?? true);
  const [result, setResult] = useState<SaveItemResult | null>(null);
  const [pending, startTransition] = useTransition();

  const fieldError = (field: "name" | "description" | "price") =>
    result && !result.ok && "field" in result && result.field === field ? result.error : null;
  const generalError = result && !result.ok && !("field" in result) ? result.error : null;

  function submit(e: React.FormEvent) {
    e.preventDefault();
    startTransition(async () => {
      const saved = await saveMenuItem({ itemId: item?.id, sectionId, name, description, price, imageUrl, isAvailable });
      setResult(saved);
      if (saved.ok) onSaved();
    });
  }

  return (
    <form onSubmit={submit} noValidate className="flex min-h-full flex-col">
      <div className="px-5 pt-6">
        <SheetTitle className="text-[1.6rem] leading-tight font-semibold tracking-[-0.02em]">
          {item ? "Edit item" : "Add item"}
        </SheetTitle>
        <SheetDescription className="mt-2">
          {item ? "Changes show on your ordering page right away." : "It appears on your ordering page as soon as you add it."}
        </SheetDescription>
      </div>

      <div className="flex-1 space-y-5 px-5 py-6">
        <PhotoField value={imageUrl} onChange={setImageUrl} />

        <Field label="Name" htmlFor="item-name" error={fieldError("name")}>
          <Input
            id="item-name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            aria-invalid={Boolean(fieldError("name"))}
            className="h-12 rounded-xl px-3.5 text-base"
          />
        </Field>

        <Field label="Description" htmlFor="item-description" error={fieldError("description")} hint="Optional. What's in it, in a sentence.">
          <textarea
            id="item-description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            rows={3}
            aria-invalid={Boolean(fieldError("description"))}
            className="w-full rounded-xl border border-input px-3.5 py-2.5 text-base outline-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50"
          />
        </Field>

        <Field label="Price" htmlFor="item-price" error={fieldError("price")}>
          <div className="flex h-12 items-center rounded-xl border border-input px-3.5 focus-within:border-ring focus-within:ring-3 focus-within:ring-ring/50">
            <span className="text-muted-foreground">$</span>
            <input
              id="item-price"
              inputMode="decimal"
              value={price}
              onChange={(e) => setPrice(e.target.value)}
              placeholder="12.50"
              aria-invalid={Boolean(fieldError("price"))}
              className="h-full min-w-0 flex-1 bg-transparent pl-1 text-base tabular-nums outline-none"
            />
          </div>
        </Field>

        <Field label="Section" htmlFor="item-section">
          <select
            id="item-section"
            value={sectionId}
            onChange={(e) => setSectionId(e.target.value)}
            className="h-12 w-full rounded-xl border border-input bg-surface px-3 text-base outline-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50"
          >
            {sections.map((s) => (
              <option key={s.id} value={s.id}>
                {s.name}
              </option>
            ))}
          </select>
        </Field>

        <label className="flex min-h-12 cursor-pointer items-center gap-3">
          <Checkbox checked={isAvailable} onCheckedChange={(checked) => setIsAvailable(checked)} />
          <span className="font-medium">In stock</span>
        </label>

        {item && item.modifierGroups.length > 0 && (
          <p className="rounded-xl bg-muted px-4 py-3 text-sm text-muted-foreground">
            Options: {item.modifierGroups.map((g) => g.name).join(", ")}. Editing options from the dashboard is coming later.
          </p>
        )}

        {generalError && <p className="text-sm font-medium text-destructive">{generalError}</p>}
      </div>

      <div className="sticky bottom-0 border-t border-border bg-surface px-5 pt-3 pb-[max(1rem,env(safe-area-inset-bottom))]">
        <Button type="submit" disabled={pending} className="h-12 w-full rounded-xl text-base font-semibold">
          {pending ? "Saving…" : item ? "Save changes" : "Add item"}
        </Button>
      </div>
    </form>
  );
}

function Field({
  label,
  htmlFor,
  hint,
  error,
  children,
}: {
  label: string;
  htmlFor: string;
  hint?: string;
  error?: string | null;
  children: React.ReactNode;
}) {
  return (
    <div>
      <Label htmlFor={htmlFor} className="mb-2 font-semibold">
        {label}
      </Label>
      {children}
      {error ? (
        <p role="alert" className="mt-1.5 text-sm font-medium text-destructive">
          {error}
        </p>
      ) : (
        hint && <p className="mt-1.5 text-sm text-muted-foreground">{hint}</p>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";

const STORAGE_KEY = "ft.chime";

function playChime(ctx: AudioContext) {
  [880, 1320].forEach((hz, i) => {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = "sine";
    osc.frequency.value = hz;
    const t = ctx.currentTime + i * 0.14;
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(0.25, t + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.22);
    osc.connect(gain).connect(ctx.destination);
    osc.start(t);
    osc.stop(t + 0.24);
  });
}

/**
 * Opt-in sound for new orders. Off by default; the tap that turns it on is the
 * user gesture the browser needs before it will play audio.
 */
export function NewOrderChime({ arrivalKey }: { arrivalKey: number }) {
  const [on, setOn] = useState(false);
  const ctxRef = useRef<AudioContext | null>(null);

  // localStorage is only readable after mount.
  useEffect(() => {
    try {
      setOn(localStorage.getItem(STORAGE_KEY) === "on");
    } catch {}
  }, []);

  useEffect(() => {
    // After a reload with the pref on, no tap has happened yet, so there is no
    // AudioContext until the vendor taps the toggle or the page once.
    if (arrivalKey === 0 || !on) return;
    ctxRef.current ??= new AudioContext();
    const ctx = ctxRef.current;
    if (ctx.state === "suspended") void ctx.resume();
    playChime(ctx);
  }, [arrivalKey, on]);

  function toggle() {
    const next = !on;
    if (next) {
      ctxRef.current ??= new AudioContext();
      void ctxRef.current.resume();
      playChime(ctxRef.current); // a preview, so the vendor knows what it sounds like
    }
    setOn(next);
    try {
      localStorage.setItem(STORAGE_KEY, next ? "on" : "off");
    } catch {}
  }

  return (
    <button
      type="button"
      aria-pressed={on}
      aria-label="Chime for new orders"
      onClick={toggle}
      className={cn(
        "flex size-11 shrink-0 items-center justify-center rounded-xl text-lg outline-none focus-visible:ring-2 focus-visible:ring-foreground/40",
        on ? "bg-foreground text-background" : "text-muted-foreground"
      )}
    >
      <span aria-hidden>♪</span>
    </button>
  );
}

"use client";

import { useEffect, useState, useTransition } from "react";
import { createTruck, joinDemo, type CreateTruckResult } from "@/app/(dashboard)/dashboard/actions";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

const TIMEZONES = [
  { value: "America/New_York", label: "Eastern (New York)" },
  { value: "America/Chicago", label: "Central (Chicago)" },
  { value: "America/Denver", label: "Mountain (Denver)" },
  { value: "America/Phoenix", label: "Arizona (Phoenix)" },
  { value: "America/Los_Angeles", label: "Pacific (Los Angeles)" },
  { value: "America/Anchorage", label: "Alaska (Anchorage)" },
  { value: "Pacific/Honolulu", label: "Hawaii (Honolulu)" },
];

const slugify = (s: string) =>
  s
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40);

export function OnboardingForm({ appHost, demoAllowed }: { appHost: string; demoAllowed: boolean }) {
  const [name, setName] = useState("");
  const [slug, setSlug] = useState("");
  const [slugEdited, setSlugEdited] = useState(false);
  const [timezone, setTimezone] = useState("America/Chicago");
  const [zones, setZones] = useState(TIMEZONES);
  const [result, setResult] = useState<CreateTruckResult | null>(null);
  const [pending, startTransition] = useTransition();

  // Default to the vendor's own timezone.
  useEffect(() => {
    const local = Intl.DateTimeFormat().resolvedOptions().timeZone;
    if (!local) return;
    setTimezone(local);
    if (!TIMEZONES.some((z) => z.value === local)) setZones([{ value: local, label: local }, ...TIMEZONES]);
  }, []);

  const shownSlug = slugEdited ? slug : slugify(name);
  const errorFor = (field: "name" | "slug" | "timezone") =>
    result && !result.ok && result.field === field ? result.error : null;
  const generalError = result && !result.ok && !result.field ? result.error : null;

  function submit(e: React.FormEvent) {
    e.preventDefault();
    startTransition(async () => setResult(await createTruck({ name, slug: shownSlug, timezone })));
  }

  return (
    <>
      <form onSubmit={submit} noValidate className="mt-8 space-y-5 rounded-2xl bg-surface p-5">
        <div>
          <Label htmlFor="truck-name" className="mb-2 font-semibold">
            Truck name
          </Label>
          <Input
            id="truck-name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Taco Libre"
            aria-invalid={Boolean(errorFor("name"))}
            className="h-12 rounded-xl px-3.5 text-base"
          />
          {errorFor("name") && <p className="mt-1.5 text-sm font-medium text-destructive">{errorFor("name")}</p>}
        </div>

        <div>
          <Label htmlFor="truck-slug" className="mb-2 font-semibold">
            Ordering page address
          </Label>
          <div className="flex h-12 items-center rounded-xl border border-input px-3.5 focus-within:border-ring focus-within:ring-3 focus-within:ring-ring/50">
            <span className="text-muted-foreground">{appHost}/</span>
            <input
              id="truck-slug"
              value={shownSlug}
              onChange={(e) => {
                setSlugEdited(true);
                setSlug(slugify(e.target.value));
              }}
              aria-invalid={Boolean(errorFor("slug"))}
              className="h-full min-w-0 flex-1 bg-transparent text-base outline-none"
            />
          </div>
          {errorFor("slug") ? (
            <p className="mt-1.5 text-sm font-medium text-destructive">{errorFor("slug")}</p>
          ) : (
            <p className="mt-1.5 text-sm text-muted-foreground">Customers order from this link.</p>
          )}
        </div>

        <div>
          <Label htmlFor="truck-tz" className="mb-2 font-semibold">
            Timezone
          </Label>
          <select
            id="truck-tz"
            value={timezone}
            onChange={(e) => setTimezone(e.target.value)}
            className="h-12 w-full rounded-xl border border-input bg-surface px-3 text-base outline-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50"
          >
            {zones.map((z) => (
              <option key={z.value} value={z.value}>
                {z.label}
              </option>
            ))}
          </select>
          <p className="mt-1.5 text-sm text-muted-foreground">Pickup times show in this timezone.</p>
        </div>

        {generalError && <p className="text-sm font-medium text-destructive">{generalError}</p>}

        <Button type="submit" disabled={pending} className="h-12 w-full rounded-xl text-base font-semibold">
          {pending ? "Creating your truck…" : "Create my truck"}
        </Button>
      </form>

      {demoAllowed && (
        <div className="mt-6 rounded-2xl border border-dashed border-border p-5">
          <p className="font-semibold">Just trying things out?</p>
          <p className="mt-1 text-sm text-muted-foreground">
            Manage the seeded demo truck, Ranger Truck, with its menu and sample orders.
          </p>
          <Button
            variant="outline"
            disabled={pending}
            onClick={() => startTransition(async () => setResult(await joinDemo()))}
            className="mt-4 h-11 rounded-xl px-4 text-base"
          >
            Manage the demo truck
          </Button>
        </div>
      )}
    </>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { ChevronRight } from "lucide-react";
import type { OrderView } from "@/lib/types";
import { formatCents } from "@/lib/money";
import { ACTIVE_STATUSES, ADVANCE_LABEL, isAdvanceable } from "@/lib/orders/status";
import { cn } from "@/lib/utils";
import { advanceOrder, cancelOrderAction } from "@/app/(dashboard)/dashboard/actions";
import { voidLineItem } from "@/app/(dashboard)/dashboard/(app)/orders/actions";

type Reason = "SOLD_OUT" | "CUSTOMER_REQUEST" | "MISTAKE";
const REASONS: { value: Reason; label: string }[] = [
  { value: "SOLD_OUT", label: "Sold out" },
  { value: "CUSTOMER_REQUEST", label: "Customer" },
  { value: "MISTAKE", label: "Mistake" },
];

const focusRing = "outline-none focus-visible:ring-4 focus-visible:ring-foreground/30";

type Props = { order: OrderView; truckName: string; pickupLabel: string };

/** Everything on the detail page that does something: advance, contact, void an item, cancel. */
export function OrderDetailActions({ order, truckName, pickupLabel }: Props) {
  const isActive = ACTIVE_STATUSES.includes(order.status);
  const canVoid = isActive || order.status === "PICKED_UP";

  return (
    <div className="border-t border-border">
      {isActive && <AdvanceButton order={order} />}
      <Contact order={order} truckName={truckName} />
      {canVoid && <IssueBlock order={order} pickupLabel={pickupLabel} canCancel={isActive} />}
    </div>
  );
}

function AdvanceButton({ order }: { order: OrderView }) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);
  if (!isAdvanceable(order.status)) return null;
  const from = order.status;
  const tone = from === "PAID" ? "new" : from === "READY" ? "ready" : "cooking";

  return (
    <div className="px-4 pt-4">
      <button
        type="button"
        disabled={pending}
        onClick={() =>
          startTransition(async () => {
            const result = await advanceOrder({ orderId: order.id, from });
            setError(result.ok ? null : result.error);
            router.refresh();
          })
        }
        className={cn(
          "h-14 w-full rounded-xl border text-[1.0625rem] font-bold disabled:opacity-60",
          focusRing,
          tone === "new" && "border-new bg-new text-new-foreground hover:bg-new/90",
          tone === "cooking" && "border-cooking bg-cooking-tint text-cooking-ink hover:bg-cooking-tint/70",
          tone === "ready" && "border-ready bg-ready-tint-strong text-ready-ink hover:bg-ready-tint-strong/70"
        )}
      >
        {ADVANCE_LABEL[from]}
      </button>
      {error && (
        <p role="alert" className="mt-2 text-[0.9375rem] font-medium text-destructive">
          {error}
        </p>
      )}
    </div>
  );
}

function Contact({ order, truckName }: { order: OrderView; truckName: string }) {
  const first = order.customerName.trim().split(/\s+/)[0] || "customer";
  // A counter sale has no phone, so there is nobody to call or text.
  const phone = order.customerPhone;
  const digits = phone?.replace(/[^\d+]/g, "") ?? "";
  const message = `Hi ${first}, this is ${truckName} about order ${order.orderNumber}.`;
  const button = cn(
    "flex h-12 flex-1 items-center justify-center rounded-xl border border-border px-2 font-semibold",
    focusRing
  );

  return (
    <div className="px-4 pt-4">
      {phone && (
        <>
          <div className="flex gap-2">
            <a href={`tel:${digits}`} className={button}>
              Call {first}
            </a>
            <a href={`sms:${digits}?&body=${encodeURIComponent(message)}`} className={button}>
              Text {first}
            </a>
          </div>
          <p className="mt-3 text-[0.9375rem] text-muted-foreground tabular-nums select-text">{phone}</p>
        </>
      )}
      {order.customerEmail && (
        <>
          <a
            href={`mailto:${order.customerEmail}?subject=${encodeURIComponent(`Your order ${order.orderNumber} from ${truckName}`)}`}
            className={cn(button, "mt-3 w-full flex-none")}
          >
            Email {first}
          </a>
          <p className="mt-2 text-[0.9375rem] break-all text-muted-foreground select-text">{order.customerEmail}</p>
        </>
      )}
    </div>
  );
}

function IssueBlock({ order, pickupLabel, canCancel }: { order: OrderView; pickupLabel: string; canCancel: boolean }) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [lineId, setLineId] = useState<string | null>(null);
  const [reason, setReason] = useState<Reason | null>(null);
  const [refund, setRefund] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [confirming, setConfirming] = useState(false);

  const selected = order.lines.find((l) => l.id === lineId && !l.voidedAt) ?? null;
  const ready = selected !== null && reason !== null;

  function removeItem() {
    if (!selected || !reason) return;
    startTransition(async () => {
      const result = await voidLineItem({ orderId: order.id, lineItemId: selected.id, reason, refund });
      setError(result.ok ? null : result.error);
      if (result.ok) {
        setLineId(null);
        setReason(null);
      }
      router.refresh();
    });
  }

  function cancel() {
    startTransition(async () => {
      const result = await cancelOrderAction(order.id);
      if (result.ok) {
        router.push("/dashboard");
      } else {
        setError(result.error);
        setConfirming(false);
        router.refresh();
      }
    });
  }

  return (
    <details className="group mx-4 mt-6 rounded-xl border border-border">
      <summary
        className={cn(
          "flex h-12 cursor-pointer list-none items-center justify-between rounded-xl px-4 font-semibold [&::-webkit-details-marker]:hidden",
          focusRing
        )}
      >
        Issue with this order
        <ChevronRight aria-hidden className="size-5 transition-transform group-open:rotate-90" />
      </summary>

      <div className="border-t border-border px-4 py-4">
        <fieldset>
          <legend className="font-semibold">Remove an item</legend>
          <div className="mt-2 divide-y divide-border">
            {order.lines.map((line) => (
              <label
                key={line.id}
                className={cn(
                  "flex min-h-12 items-center gap-3 py-2 text-[0.9375rem]",
                  line.voidedAt ? "opacity-60" : "cursor-pointer"
                )}
              >
                <input
                  type="radio"
                  name="line"
                  value={line.id}
                  disabled={line.voidedAt !== null}
                  checked={lineId === line.id}
                  onChange={() => setLineId(line.id)}
                  className="size-5 shrink-0 accent-foreground"
                />
                <span className="min-w-0 flex-1 break-words">
                  <span className="font-semibold tabular-nums">{line.quantity}×</span> {line.name}
                </span>
                <span className="shrink-0 text-muted-foreground tabular-nums">
                  {line.voidedAt ? "already removed" : formatCents(line.lineTotalCents)}
                </span>
              </label>
            ))}
          </div>
        </fieldset>

        <fieldset className="mt-4">
          <legend className="font-semibold">Why?</legend>
          <div className="mt-2 grid grid-cols-3 gap-2">
            {REASONS.map((r) => (
              <label
                key={r.value}
                className={cn(
                  "flex h-12 cursor-pointer items-center justify-center rounded-xl border border-border text-[0.9375rem] font-semibold has-[:focus-visible]:ring-4 has-[:focus-visible]:ring-foreground/30",
                  reason === r.value && "border-foreground bg-muted"
                )}
              >
                <input
                  type="radio"
                  name="reason"
                  value={r.value}
                  checked={reason === r.value}
                  onChange={() => setReason(r.value)}
                  required
                  className="sr-only"
                />
                {r.label}
              </label>
            ))}
          </div>
        </fieldset>

        <label className="mt-4 flex min-h-12 cursor-pointer items-center gap-3 text-[0.9375rem]">
          <input
            type="checkbox"
            checked={refund}
            onChange={(e) => setRefund(e.target.checked)}
            className="size-5 shrink-0 accent-foreground"
          />
          <span>Record a {selected ? formatCents(selected.lineTotalCents) : "$0.00"} refund owed</span>
        </label>

        <button
          type="button"
          disabled={!ready || pending}
          onClick={removeItem}
          className={cn(
            "mt-3 h-12 w-full rounded-xl border border-destructive bg-surface font-semibold text-destructive hover:bg-destructive/10 disabled:opacity-50",
            focusRing
          )}
        >
          Remove item
        </button>
        <p className="mt-2 text-[0.8125rem] text-muted-foreground">
          Nothing is charged or refunded yet. Settle with the customer at the window.
        </p>
        {/* TODO(Stream C): the partial Stripe refund for the voided line goes here (via voidOrderLineItem). */}

        {error && (
          <p role="alert" className="mt-3 text-[0.9375rem] font-medium text-destructive">
            {error}
          </p>
        )}

        {canCancel && (
          <div className="mt-5 border-t border-border pt-4">
            <button
              type="button"
              disabled={pending}
              onClick={() => (confirming ? cancel() : setConfirming(true))}
              onBlur={() => setConfirming(false)}
              className={cn(
                "h-12 w-full rounded-xl bg-destructive font-semibold text-white disabled:opacity-60",
                focusRing,
                confirming && "ring-4 ring-destructive/30"
              )}
            >
              {confirming ? "Tap again to cancel this order" : "Cancel order"}
            </button>
            <p className="mt-2 text-[0.8125rem] text-muted-foreground">
              Cancels every item and frees the {pickupLabel} pickup slot.
            </p>
          </div>
        )}
      </div>
    </details>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";
import { Lock, MapPin, Search as SearchIcon } from "lucide-react";
import type { Suggestion } from "@/lib/geo/types";
import { singleLineAddress } from "@/lib/service";
import type { Location } from "@/lib/types";
import { cn } from "@/lib/utils";
import { Input } from "@/components/ui/input";

/** Where a stop is: a saved spot, a fresh geocoder result, or an address typed by hand. */
export type PlaceValue =
  | { kind: "saved"; location: Location; reused?: boolean }
  | { kind: "found"; provider: "geoapify" | "photon"; suggestion: Suggestion; name: string; notes: string }
  | { kind: "manual"; name: string; addressLine: string; city: string; region: string; postcode: string; notes: string };

/** The slice of saveStop / saveSpot input that describes the place. */
export function placeInput(value: PlaceValue) {
  if (value.kind === "saved") return { locationId: value.location.id };
  if (value.kind === "found") {
    const s = value.suggestion;
    return {
      place: {
        provider: value.provider,
        providerPlaceId: s.providerPlaceId,
        name: value.name,
        addressLine: s.addressLine,
        city: s.city,
        region: s.region,
        postcode: s.postcode,
        lat: s.lat,
        lng: s.lng,
        notes: value.notes,
      },
    };
  }
  const { name, addressLine, city, region, postcode, notes } = value;
  return { place: { provider: "manual" as const, providerPlaceId: null, lat: null, lng: null, name, addressLine, city, region, postcode, notes } };
}

type Result = { q: string; suggestions: Suggestion[]; provider: string; failed: string | null };
type Option = { type: "spot"; location: Location } | { type: "suggestion"; suggestion: Suggestion };

const DEBOUNCE_MS = 300;

type Props = {
  value: PlaceValue | null;
  onChange: (value: PlaceValue | null) => void;
  spots: Location[];
  error?: string | null;
  /** Set when the spot can't change (the stop has orders): shown instead of the Change button. */
  lockedReason?: string;
  /** Accessible name for the search box. Defaults to the schedule's wording. */
  label?: string;
};

export function PlaceCombobox({ value, onChange, spots, error, lockedReason, label }: Props) {
  if (value) return <ConfirmBlock value={value} onChange={onChange} error={error} lockedReason={lockedReason} />;
  return <SearchPhase spots={spots} onChange={onChange} error={error} label={label} />;
}

// ─── Search ────────────────────────────────────────────────────────────────

function SearchPhase({ spots, onChange, error, label = "Where is this stop?" }: Pick<Props, "spots" | "onChange" | "error" | "label">) {
  const uid = useId();
  const listId = `${uid}-list`;
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);
  const [result, setResult] = useState<Result | null>(null);
  const listRef = useRef<HTMLUListElement>(null);

  const q = query.trim();
  const searching = q.length >= 3;
  const loading = searching && result?.q !== q;

  // Debounced lookup. Only async callbacks set state, so a stale response can't land.
  useEffect(() => {
    if (!searching) return;
    const controller = new AbortController();
    const timer = setTimeout(async () => {
      try {
        const res = await fetch(`/api/geo/suggest?q=${encodeURIComponent(q)}`, { signal: controller.signal });
        const body = (await res.json().catch(() => null)) as { provider?: string; suggestions?: Suggestion[]; degraded?: boolean; error?: string } | null;
        if (!res.ok) setResult({ q, suggestions: [], provider: "", failed: body?.error ?? "Address search isn't working right now." });
        else setResult({ q, suggestions: body?.suggestions ?? [], provider: body?.provider ?? "geoapify", failed: body?.degraded ? "Address search isn't responding." : null });
      } catch (e) {
        if ((e as Error).name !== "AbortError") setResult({ q, suggestions: [], provider: "", failed: "Address search isn't working right now." });
      }
    }, DEBOUNCE_MS);
    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [q, searching]);

  // Saved spots: all of them while empty, the matching ones while typing.
  const needle = q.toLowerCase();
  const matchingSpots = spots.filter((s) => !needle || `${s.name} ${s.addressLine} ${s.city}`.toLowerCase().includes(needle));
  const suggestions = searching && result?.q === q ? result.suggestions : [];
  const options: Option[] = [
    ...matchingSpots.map((location): Option => ({ type: "spot", location })),
    ...suggestions.map((suggestion): Option => ({ type: "suggestion", suggestion })),
  ];
  const activeIndex = Math.min(active, options.length - 1);

  useEffect(() => {
    listRef.current?.querySelector(`[data-index="${activeIndex}"]`)?.scrollIntoView({ block: "nearest" });
  }, [activeIndex]);

  function pick(option: Option) {
    if (option.type === "spot") return onChange({ kind: "saved", location: option.location });
    const s = option.suggestion;
    const provider = result?.provider === "photon" ? "photon" : "geoapify";
    const known = s.providerPlaceId ? spots.find((x) => x.provider === provider && x.providerPlaceId === s.providerPlaceId) : undefined;
    if (known) return onChange({ kind: "saved", location: known, reused: true });
    onChange({ kind: "found", provider, suggestion: s, name: s.suggestedName, notes: "" });
  }

  function onKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      if (!open) return setOpen(true);
      if (!options.length) return;
      const step = e.key === "ArrowDown" ? 1 : -1;
      setActive((activeIndex + step + options.length) % options.length);
    } else if (e.key === "Enter") {
      // Never submit the form from here.
      e.preventDefault();
      if (open && options[activeIndex]) pick(options[activeIndex]);
    } else if (e.key === "Escape" && open) {
      // Close the list, not the sheet around it.
      e.preventDefault();
      e.stopPropagation();
      setOpen(false);
    }
  }

  const showList = open && (options.length > 0 || searching);
  let note: string | null = null;
  if (searching && !loading && !suggestions.length) note = result?.failed ?? "No addresses found.";
  else if (searching && result?.failed) note = result.failed;

  return (
    <div>
      <div className="relative">
        <SearchIcon className="pointer-events-none absolute top-1/2 left-3.5 size-4 -translate-y-1/2 text-muted-foreground" aria-hidden />
        <Input
          role="combobox"
          aria-expanded={showList}
          aria-controls={listId}
          aria-autocomplete="list"
          aria-activedescendant={showList && activeIndex >= 0 ? `${uid}-opt-${activeIndex}` : undefined}
          aria-label={label}
          aria-invalid={Boolean(error)}
          autoComplete="off"
          autoCorrect="off"
          spellCheck={false}
          value={query}
          placeholder={spots.length ? "Pick a spot or type an address" : "Type an address or a place"}
          onChange={(e) => {
            setQuery(e.target.value);
            setActive(-1);
            setOpen(true);
          }}
          onFocus={() => setOpen(true)}
          onBlur={() => setOpen(false)}
          onKeyDown={onKeyDown}
          className="h-12 rounded-xl pr-3.5 pl-10 text-base focus-visible:ring-4"
        />
      </div>

      {showList && (
        <ul
          id={listId}
          ref={listRef}
          role="listbox"
          aria-label="Places"
          // Keep focus in the input while tapping an option.
          onMouseDown={(e) => e.preventDefault()}
          className="mt-2 max-h-72 overflow-y-auto overscroll-contain rounded-xl border border-border bg-surface"
        >
          {options.map((option, i) => {
            const isSpot = option.type === "spot";
            const primary = isSpot ? option.location.name : option.suggestion.primary;
            const secondary = isSpot ? singleLineAddress(option.location) : option.suggestion.secondary;
            const heading = i === 0 || options[i - 1].type !== option.type ? (isSpot ? "Your spots" : "Addresses") : null;
            return (
              <li key={isSpot ? option.location.id : `${i}-${option.suggestion.providerPlaceId}`} role="presentation" className="border-b border-border last:border-b-0">
                {heading && (
                  <p role="presentation" className="bg-muted/50 px-3.5 py-1.5 text-xs font-medium text-muted-foreground">
                    {heading}
                  </p>
                )}
                <div
                  id={`${uid}-opt-${i}`}
                  data-index={i}
                  role="option"
                  aria-selected={i === activeIndex}
                  onClick={() => pick(option)}
                  onMouseMove={() => i !== activeIndex && setActive(i)}
                  className={cn("flex cursor-pointer items-start gap-3 px-3.5 py-3", i === activeIndex && "bg-muted")}
                >
                  <MapPin className="mt-0.5 size-4 shrink-0 text-muted-foreground" strokeWidth={1.75} aria-hidden />
                  <span className="min-w-0">
                    <span className="block truncate font-semibold">{primary}</span>
                    {secondary && <span className="block truncate text-sm text-muted-foreground">{secondary}</span>}
                  </span>
                </div>
              </li>
            );
          })}
          {loading && (
            <li role="presentation" className="px-3.5 py-3 text-sm text-muted-foreground">
              Searching…
            </li>
          )}
          {note && (
            <li role="presentation" className="px-3.5 py-3 text-sm text-muted-foreground">
              {note}
            </li>
          )}
        </ul>
      )}

      {error && (
        <p role="alert" data-field-error className="mt-2 text-sm font-medium text-destructive">
          {error}
        </p>
      )}

      <p className="mt-2.5 text-sm text-muted-foreground">
        Not finding it?{" "}
        <button
          type="button"
          onClick={() => onChange({ kind: "manual", name: "", addressLine: "", city: "", region: "", postcode: "", notes: "" })}
          className="rounded-sm font-medium text-brand underline-offset-4 outline-none hover:underline focus-visible:ring-4 focus-visible:ring-ring/40"
        >
          Enter it manually
        </button>
      </p>
    </div>
  );
}

// ─── Confirm block ─────────────────────────────────────────────────────────

function ConfirmBlock({ value, onChange, error, lockedReason }: { value: PlaceValue; onChange: Props["onChange"]; error?: string | null; lockedReason?: string }) {
  const uid = useId();
  const place = value.kind === "saved" ? value.location : value.kind === "found" ? value.suggestion : null;

  return (
    <div>
      <div className="flex items-start gap-3">
        <div className="min-w-0 flex-1">
          {value.kind === "saved" && <p className="truncate font-semibold">{value.location.name}</p>}
          {place && <p className={cn("text-sm", value.kind === "saved" ? "text-muted-foreground" : "font-medium")}>{singleLineAddress(place)}</p>}
          {value.kind === "manual" && <p className="font-medium">Enter the address</p>}
          {value.kind === "saved" && value.location.notes && <p className="mt-0.5 text-sm text-muted-foreground">{value.location.notes}</p>}
          {value.kind === "saved" && value.reused && <p className="mt-1 text-sm font-medium text-ok">You already have a spot here.</p>}
        </div>
        {!lockedReason && (
          <button
            type="button"
            onClick={() => onChange(null)}
            className="-my-1 h-9 shrink-0 rounded-full px-3 text-sm font-semibold text-brand outline-none hover:bg-muted focus-visible:ring-4 focus-visible:ring-ring/40"
          >
            Change
          </button>
        )}
      </div>

      {lockedReason && (
        <p className="mt-2 flex items-start gap-2 text-sm text-muted-foreground">
          <Lock className="mt-0.5 size-3.5 shrink-0" aria-hidden />
          {lockedReason}
        </p>
      )}

      {value.kind === "found" && (
        <div className="mt-4 space-y-4">
          <TextField id={`${uid}-name`} label="Name this spot" hint="Customers see this as the headline." value={value.name} onChange={(name) => onChange({ ...value, name })} />
          <TextField
            id={`${uid}-notes`}
            label="Parking note (optional)"
            placeholder="Patio side, by the loading door."
            value={value.notes}
            onChange={(notes) => onChange({ ...value, notes })}
          />
        </div>
      )}

      {value.kind === "manual" && (
        <div className="mt-4 space-y-4">
          <TextField id={`${uid}-name`} label="Name this spot" hint="Customers see this as the headline." value={value.name} onChange={(name) => onChange({ ...value, name })} />
          <TextField id={`${uid}-address`} label="Street address" autoComplete="street-address" value={value.addressLine} onChange={(addressLine) => onChange({ ...value, addressLine })} />
          <div className="grid grid-cols-[1fr_5rem_6rem] gap-3">
            <TextField id={`${uid}-city`} label="City" value={value.city} onChange={(city) => onChange({ ...value, city })} />
            <TextField id={`${uid}-region`} label="State" value={value.region} onChange={(region) => onChange({ ...value, region })} />
            <TextField id={`${uid}-zip`} label="Zip" inputMode="numeric" value={value.postcode} onChange={(postcode) => onChange({ ...value, postcode })} />
          </div>
          <TextField
            id={`${uid}-notes`}
            label="Parking note (optional)"
            placeholder="Patio side, by the loading door."
            value={value.notes}
            onChange={(notes) => onChange({ ...value, notes })}
          />
        </div>
      )}

      {error && (
        <p role="alert" data-field-error className="mt-3 text-sm font-medium text-destructive">
          {error}
        </p>
      )}
    </div>
  );
}

export function TextField({
  id,
  label,
  hint,
  value,
  onChange,
  ...rest
}: { id: string; label: string; hint?: string; value: string; onChange: (value: string) => void } & Omit<React.ComponentProps<"input">, "onChange" | "value" | "id">) {
  return (
    <div className="min-w-0">
      <label htmlFor={id} className="mb-1.5 block text-sm font-semibold">
        {label}
      </label>
      <Input id={id} value={value} onChange={(e) => onChange(e.target.value)} aria-describedby={hint ? `${id}-hint` : undefined} className="h-12 rounded-xl px-3.5 text-base" {...rest} />
      {hint && (
        <p id={`${id}-hint`} className="mt-1.5 text-sm text-muted-foreground">
          {hint}
        </p>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { ChevronLeft } from "lucide-react";
import type { MenuItem, ModifierGroup } from "@/lib/types";
import { formatCents, unitPriceCents } from "@/lib/money";
import { cn } from "@/lib/utils";
import { chosenOptionIds, unmetGroup, type Selections } from "@/lib/menu/selections";
import { Checkbox } from "@/components/ui/checkbox";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Sheet, SheetContent, SheetDescription, SheetTitle } from "@/components/ui/sheet";

type Props = {
  item: MenuItem;
  initial: Selections;
  mode: "add" | "edit";
  asSheet: boolean; // phone: bottom sheet. Otherwise an inline panel that replaces the tile field.
  onSubmit: (optionIds: string[]) => void;
  onCancel: () => void;
};

export function PosOptions({ item, initial, mode, asSheet, onSubmit, onCancel }: Props) {
  const body = <OptionsBody key={item.id} item={item} initial={initial} mode={mode} asSheet={asSheet} onSubmit={onSubmit} onCancel={onCancel} />;

  if (!asSheet) return body;
  return (
    <Sheet open onOpenChange={(open) => !open && onCancel()}>
      <SheetContent side="bottom" showCloseButton={false} className="max-h-[92dvh] gap-0 rounded-t-3xl border-0 bg-surface p-0 shadow-none">
        <SheetTitle className="sr-only">{item.name} options</SheetTitle>
        <SheetDescription className="sr-only">Choose options for {item.name}.</SheetDescription>
        {body}
      </SheetContent>
    </Sheet>
  );
}

function OptionsBody({ item, initial, mode, asSheet, onSubmit, onCancel }: Props) {
  const [selections, setSelections] = useState<Selections>(initial);
  const unmet = unmetGroup(item, selections);
  const optionIds = chosenOptionIds(selections);
  const priceCents = unitPriceCents(item, optionIds);

  return (
    <div className={cn("flex flex-col bg-surface", asSheet ? "max-h-[92dvh]" : "h-full min-h-0")}>
      <div className="flex items-center gap-2 border-b border-border px-4 py-2">
        <button
          type="button"
          onClick={onCancel}
          className="-ml-2 inline-flex h-11 items-center gap-1 rounded-xl px-2 text-[0.9375rem] font-semibold text-muted-foreground outline-none focus-visible:ring-4 focus-visible:ring-foreground/30"
        >
          <ChevronLeft className="size-4" /> {mode === "add" ? "Back to dishes" : "Cancel"}
        </button>
      </div>

      <div className="min-h-0 flex-1 overflow-y-auto px-4 pb-4">
        <h2 className="pt-4 text-[1.5rem] leading-tight font-semibold tracking-[-0.02em]">{item.name}</h2>
        {item.modifierGroups.map((group) => (
          <GroupField
            key={group.id}
            group={group}
            value={selections[group.id] ?? []}
            onChange={(ids) => setSelections((s) => ({ ...s, [group.id]: ids }))}
          />
        ))}
      </div>

      <div className="border-t border-border bg-surface px-4 pt-3 pb-[max(1rem,env(safe-area-inset-bottom))]">
        {unmet && <p className="mb-2 text-[0.8125rem] text-muted-foreground">Choose a {unmet.name.toLowerCase()} to continue.</p>}
        <button
          type="button"
          disabled={Boolean(unmet)}
          onClick={() => onSubmit(optionIds)}
          className="flex h-16 w-full items-center justify-between rounded-xl bg-foreground px-5 text-[1.0625rem] font-bold text-background outline-none focus-visible:ring-4 focus-visible:ring-foreground/30 disabled:opacity-40"
        >
          <span>{mode === "add" ? "Add" : "Update"}</span>
          <span className="tabular-nums">{formatCents(priceCents)}</span>
        </button>
      </div>
    </div>
  );
}

function requirementText(group: ModifierGroup): string {
  if (group.required && group.maxSelect === 1) return "Required";
  if (group.required) return `Required, pick ${group.minSelect}–${group.maxSelect}`;
  return group.maxSelect === 1 ? "Optional" : `Optional, up to ${group.maxSelect}`;
}

// Ink instead of the default --primary (brand) so no truck colour reaches this screen.
const inkControl =
  "size-6 data-checked:border-foreground data-checked:bg-foreground data-checked:text-background focus-visible:border-foreground focus-visible:ring-4 focus-visible:ring-foreground/30";

function GroupField({ group, value, onChange }: { group: ModifierGroup; value: string[]; onChange: (ids: string[]) => void }) {
  const single = group.maxSelect === 1;
  const atMax = value.length >= group.maxSelect;

  return (
    <fieldset className="mt-6">
      <legend className="flex w-full items-baseline justify-between gap-4">
        <span className="text-[1.0625rem] font-semibold">{group.name}</span>
        <span className="text-[0.8125rem] text-muted-foreground">{requirementText(group)}</span>
      </legend>
      <div className="mt-1 divide-y divide-border border-y border-border">
        {single ? (
          <RadioGroup value={value[0] ?? null} onValueChange={(v) => onChange(v ? [v as string] : [])} className="gap-0 divide-y divide-border">
            {group.options.map((option) => (
              <OptionRow key={option.id} name={option.name} deltaCents={option.priceDeltaCents} soldOut={!option.isAvailable}>
                <RadioGroupItem value={option.id} disabled={!option.isAvailable} className={inkControl} />
              </OptionRow>
            ))}
          </RadioGroup>
        ) : (
          group.options.map((option) => {
            const checked = value.includes(option.id);
            return (
              <OptionRow key={option.id} name={option.name} deltaCents={option.priceDeltaCents} soldOut={!option.isAvailable}>
                <Checkbox
                  checked={checked}
                  disabled={!option.isAvailable || (!checked && atMax)}
                  onCheckedChange={(next) => onChange(next ? [...value, option.id] : value.filter((id) => id !== option.id))}
                  className={inkControl}
                />
              </OptionRow>
            );
          })
        )}
      </div>
    </fieldset>
  );
}

function OptionRow({ name, deltaCents, soldOut, children }: { name: string; deltaCents: number; soldOut: boolean; children: React.ReactNode }) {
  return (
    <label className={cn("flex min-h-14 cursor-pointer items-center gap-3 py-2", soldOut && "cursor-not-allowed text-muted-foreground")}>
      {children}
      <span className="flex-1 text-[0.9375rem]">{name}</span>
      <span className="text-[0.8125rem] text-muted-foreground tabular-nums">
        {soldOut ? "Sold out" : deltaCents > 0 ? `+${formatCents(deltaCents)}` : null}
      </span>
    </label>
  );
}

"use client";

import { useMemo, useState, useSyncExternalStore } from "react";
import type { ManagedSection, MenuItem } from "@/lib/types";
import { bpsToPercentInput, formatCents } from "@/lib/money";
import { defaultSelections, selectionsFromIds, unmetGroup } from "@/lib/menu/selections";
import { Sheet, SheetContent, SheetDescription, SheetTitle } from "@/components/ui/sheet";
import { CategoryRail } from "@/components/dashboard/pos/category-rail";
import { DishGrid } from "@/components/dashboard/pos/dish-grid";
import { CheckPanel } from "@/components/dashboard/pos/check-panel";
import { PosOptions } from "@/components/dashboard/pos/pos-options";
import { TenderStep, type Tender } from "@/components/dashboard/pos/tender-step";
import { CashPad } from "@/components/dashboard/pos/cash-pad";
import { SaleClosed } from "@/components/dashboard/pos/sale-closed";
import { useCheck, type DisplayLine } from "@/components/dashboard/pos/use-check";

type Props = { sections: ManagedSection[]; taxRateBps: number };

type Flow =
  | { step: "check" }
  | { step: "tender" }
  | { step: "cash" }
  | { step: "closed"; tender: Tender; totalCents: number; changeCents: number };

type OptionsTarget = { item: MenuItem; lineKey: string | null; initial: ReturnType<typeof defaultSelections> };

const MD = "(min-width: 768px)";

function useIsWide(): boolean {
  return useSyncExternalStore(
    (notify) => {
      const mq = window.matchMedia(MD);
      mq.addEventListener("change", notify);
      return () => mq.removeEventListener("change", notify);
    },
    () => window.matchMedia(MD).matches,
    () => false
  );
}

export function PosScreen({ sections, taxRateBps }: Props) {
  const allItems = useMemo(() => sections.flatMap((s) => s.items), [sections]);
  const check = useCheck(allItems, taxRateBps);
  const wide = useIsWide();

  const [sectionId, setSectionId] = useState(sections[0]?.id ?? "");
  const [flow, setFlow] = useState<Flow>({ step: "check" });
  const [options, setOptions] = useState<OptionsTarget | null>(null);
  const [sheetOpen, setSheetOpen] = useState(false);

  const section = sections.find((s) => s.id === sectionId) ?? sections[0];
  const { totalCents } = check.totals;

  function onDish(item: MenuItem) {
    if (!item.isAvailable) return;
    if (flow.step !== "check") setFlow({ step: "check" });
    const defaults = defaultSelections(item);
    // Routing by decision cost: any required group (or an unmet minimum) asks first;
    // optional-only groups add straight through.
    const needsPanel = item.modifierGroups.some((g) => g.required) || Boolean(unmetGroup(item, defaults));
    if (needsPanel) setOptions({ item, lineKey: null, initial: defaults });
    else check.add(item.id, []);
  }

  function onEditOptions(line: DisplayLine) {
    const item = allItems.find((i) => i.id === line.menuItemId);
    if (!item) return;
    setOptions({ item, lineKey: line.key, initial: selectionsFromIds(item, line.optionIds) });
  }

  function onOptionsSubmit(optionIds: string[]) {
    if (!options) return;
    if (options.lineKey) check.replaceLine(options.lineKey, options.item.id, optionIds);
    else check.add(options.item.id, optionIds);
    setOptions(null);
  }

  // The whole wiring surface for the real pipeline later: nothing persists today.
  function onPaid(tender: Tender, tenderedCents: number) {
    setFlow({ step: "closed", tender, totalCents, changeCents: Math.max(0, tenderedCents - totalCents) });
    check.clear();
  }

  function onNewSale() {
    setFlow({ step: "check" });
    setSheetOpen(false);
  }

  const footer =
    flow.step === "tender" ? (
      <TenderStep
        onBack={() => setFlow({ step: "check" })}
        onCard={() => onPaid("CARD", totalCents)}
        onCash={() => setFlow({ step: "cash" })}
        onOther={() => onPaid("OTHER", totalCents)}
      />
    ) : flow.step === "cash" ? (
      <CashPad totalCents={totalCents} onBack={() => setFlow({ step: "tender" })} onComplete={(t) => onPaid("CASH", t)} />
    ) : check.lines.length > 0 ? (
      <button
        type="button"
        onClick={() => setFlow({ step: "tender" })}
        className="flex h-16 w-full items-center justify-between rounded-xl bg-foreground px-5 text-[1.0625rem] font-bold text-background outline-none focus-visible:ring-4 focus-visible:ring-foreground/30"
      >
        <span>Charge</span>
        <span className="tabular-nums">{formatCents(totalCents)}</span>
      </button>
    ) : (
      <p className="flex h-16 items-center justify-center text-[0.9375rem] text-muted-foreground">Nothing to charge yet.</p>
    );

  const panel =
    flow.step === "closed" ? (
      <SaleClosed tender={flow.tender} totalCents={flow.totalCents} changeCents={flow.changeCents} onNewSale={onNewSale} />
    ) : (
      <CheckPanel
        lines={check.lines}
        count={check.count}
        totals={check.totals}
        taxPercent={bpsToPercentInput(taxRateBps)}
        totalsMode={flow.step === "check" ? "full" : flow.step === "tender" ? "total" : "none"}
        selectedKey={check.selectedKey}
        flash={check.flash}
        onSelect={check.setSelectedKey}
        onQuantity={check.setQuantity}
        onRemove={check.remove}
        onUndo={check.undo}
        canUndo={check.canUndo}
        onOptions={onEditOptions}
        onClear={() => {
          check.clear();
          setFlow({ step: "check" });
        }}
        onClose={wide ? undefined : () => setSheetOpen(false)}
        footer={footer}
      />
    );

  return (
    <div
      style={{ "--pos-chrome": "6.375rem" } as React.CSSProperties}
      className="flex flex-col md:flex-row lg:h-[calc(100dvh-var(--pos-chrome))] lg:overflow-hidden"
    >
      {/* Receipt paper: flush left, square, no gap. Mounted here at >=768px, in the Sheet below it. */}
      <aside
        aria-label="Check"
        className="hidden shrink-0 border-r border-border bg-surface md:sticky md:top-0 md:block md:h-[calc(100dvh-var(--pos-chrome))] md:w-[17rem] lg:static lg:h-full lg:w-[22rem] xl:w-[24rem]"
      >
        {wide && panel}
      </aside>

      {/* Menu board */}
      <main className="flex min-h-0 min-w-0 flex-1 flex-col">
        {options && wide ? (
          <PosOptions
            item={options.item}
            initial={options.initial}
            mode={options.lineKey ? "edit" : "add"}
            asSheet={false}
            onSubmit={onOptionsSubmit}
            onCancel={() => setOptions(null)}
          />
        ) : (
          <>
            <div className="shrink-0">
              <CategoryRail sections={sections} selectedId={section.id} onSelect={setSectionId} />
            </div>
            <div className="min-h-0 flex-1 overflow-y-auto">
              <DishGrid items={section.items} onSelect={onDish} />
            </div>
          </>
        )}
      </main>

      {/* Phone: sticky bar opens the same CheckPanel in a bottom Sheet. */}
      {!wide && (
        <>
          <div className="sticky bottom-0 flex items-center justify-between gap-3 border-t border-border bg-surface px-4 pt-3 pb-[max(0.75rem,env(safe-area-inset-bottom))]">
            <p className="text-[0.9375rem] font-semibold tabular-nums">
              {flow.step === "closed"
                ? "Sale closed"
                : `${check.count} ${check.count === 1 ? "item" : "items"} · ${formatCents(totalCents)}`}
            </p>
            <button
              type="button"
              onClick={() => setSheetOpen(true)}
              className="h-12 rounded-xl bg-foreground px-5 text-[1.0625rem] font-bold text-background outline-none focus-visible:ring-4 focus-visible:ring-foreground/30"
            >
              Review check
            </button>
          </div>
          <Sheet open={sheetOpen} onOpenChange={setSheetOpen}>
            <SheetContent side="bottom" showCloseButton={false} className="max-h-[92dvh] gap-0 rounded-t-3xl border-0 bg-surface p-0 shadow-none">
              <SheetTitle className="sr-only">Check</SheetTitle>
              <SheetDescription className="sr-only">Review the check and take payment.</SheetDescription>
              <div className="h-[85dvh] min-h-0">{panel}</div>
            </SheetContent>
          </Sheet>
          {options && (
            <PosOptions
              item={options.item}
              initial={options.initial}
              mode={options.lineKey ? "edit" : "add"}
              asSheet
              onSubmit={onOptionsSubmit}
              onCancel={() => setOptions(null)}
            />
          )}
        </>
      )}
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { saveSpot } from "@/app/(dashboard)/dashboard/(app)/schedule/actions";
import type { Location } from "@/lib/types";
import { Button } from "@/components/ui/button";
import { Sheet, SheetContent, SheetDescription, SheetTitle } from "@/components/ui/sheet";
import { ErrorBanner } from "@/components/dashboard/error-banner";
import { PlaceCombobox, TextField, placeInput, type PlaceValue } from "@/components/dashboard/place-combobox";

export type SpotEditing = { key: string; location: Location | null };

export function SpotSheet({ editing, onClose }: { editing: SpotEditing | null; onClose: () => void }) {
  return (
    <Sheet open={editing !== null} onOpenChange={(open) => !open && onClose()}>
      <SheetContent side="right" className="w-full gap-0 overflow-y-auto bg-surface p-0 sm:max-w-md">
        {editing && <SpotForm key={editing.key} location={editing.location} onSaved={onClose} />}
      </SheetContent>
    </Sheet>
  );
}

function SpotForm({ location, onSaved }: { location: Location | null; onSaved: () => void }) {
  // A new spot is found the same way as in a stop; an existing one is edited as plain fields.
  const [place, setPlace] = useState<PlaceValue | null>(null);
  const [fields, setFields] = useState({
    name: location?.name ?? "",
    addressLine: location?.addressLine ?? "",
    city: location?.city ?? "",
    region: location?.region ?? "",
    postcode: location?.postcode ?? "",
    notes: location?.notes ?? "",
  });
  const [error, setError] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();
  const set = (key: keyof typeof fields) => (value: string) => setFields((f) => ({ ...f, [key]: value }));

  function submit() {
    setError(null);
    let input: Parameters<typeof saveSpot>[0];
    if (location) {
      // New words for the same pin are fine; a changed address no longer matches the stored coordinates.
      const moved = (["addressLine", "city", "region", "postcode"] as const).some((k) => fields[k].trim() !== location[k]);
      input = {
        locationId: location.id,
        ...fields,
        ...(moved
          ? { provider: "manual" as const, providerPlaceId: null, lat: null, lng: null }
          : { provider: location.provider === "photon" || location.provider === "geoapify" ? location.provider : ("manual" as const), providerPlaceId: location.providerPlaceId, lat: location.lat, lng: location.lng }),
      };
    } else {
      const chosen = place ? placeInput(place) : null;
      if (!chosen || !("place" in chosen) || !chosen.place) return setError("Choose an address first.");
      input = chosen.place;
    }
    startTransition(async () => {
      const result = await saveSpot(input);
      if (result.ok) onSaved();
      else setError(result.error);
    });
  }

  return (
    <form onSubmit={(e) => e.preventDefault()} noValidate className="flex min-h-full flex-col">
      <div className="px-5 pt-6">
        <SheetTitle className="text-[1.6rem] leading-tight font-semibold tracking-[-0.02em]">{location ? "Edit spot" : "Add a spot"}</SheetTitle>
        <SheetDescription className="mt-2">
          {location ? "Stops at this spot show the new details." : "Save a place you park, then pick it in one tap when you add a stop."}
        </SheetDescription>
      </div>

      <div className="mt-6 flex-1 border-t border-border px-5 py-6">
        {location ? (
          <div className="space-y-4">
            <TextField id="spot-name" label="Name" hint="Customers see this as the headline." value={fields.name} onChange={set("name")} />
            <TextField id="spot-address" label="Street address" autoComplete="street-address" value={fields.addressLine} onChange={set("addressLine")} />
            <div className="grid grid-cols-[1fr_5rem_6rem] gap-3">
              <TextField id="spot-city" label="City" value={fields.city} onChange={set("city")} />
              <TextField id="spot-region" label="State" value={fields.region} onChange={set("region")} />
              <TextField id="spot-zip" label="Zip" inputMode="numeric" value={fields.postcode} onChange={set("postcode")} />
            </div>
            <TextField id="spot-notes" label="Parking note (optional)" placeholder="Patio side, by the loading door." value={fields.notes} onChange={set("notes")} />
          </div>
        ) : (
          <PlaceCombobox value={place} onChange={setPlace} spots={[]} />
        )}
      </div>

      <div className="sticky bottom-0 border-t border-border bg-surface px-5 pt-3 pb-[max(1rem,env(safe-area-inset-bottom))]">
        <ErrorBanner message={error} className="mb-3" />
        <Button type="button" disabled={pending} onClick={submit} className="h-12 w-full rounded-xl text-base font-semibold">
          {pending ? "Saving…" : location ? "Save changes" : "Save spot"}
        </Button>
      </div>
    </form>
  );
}

"use client";

import { useEffect, useMemo, useState, useTransition } from "react";
import { saveStop, type SaveStopResult } from "@/app/(dashboard)/dashboard/(app)/schedule/actions";
import { slotSummary } from "@/lib/schedule/slots";
import { zonedTimeFromParts } from "@/lib/time";
import type { Location, ScheduleRow, StopDraft } from "@/lib/types";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Sheet, SheetContent, SheetDescription, SheetTitle } from "@/components/ui/sheet";
import { ErrorBanner } from "@/components/dashboard/error-banner";
import { PlaceCombobox, TextField, placeInput, type PlaceValue } from "@/components/dashboard/place-combobox";
import { closesKeyFor, closesOptions, opensKeyFor, opensOptions, type ClosesKey, type OpensKey } from "@/components/dashboard/schedule/schedule-model";

export type StopEditing = {
  /** Changes per open, so the form starts fresh each time. */
  key: string;
  draft: StopDraft;
  /** Set when editing an existing stop. */
  row?: ScheduleRow;
  /** True when this draft came from Repeat: a new stop, not an edit. */
  repeated?: boolean;
};

type Props = {
  editing: StopEditing | null;
  spots: Location[];
  timeZone: string;
  onClose: () => void;
};

export function StopSheet({ editing, spots, timeZone, onClose }: Props) {
  return (
    <Sheet open={editing !== null} onOpenChange={(open) => !open && onClose()}>
      <SheetContent side="right" className="w-full gap-0 overflow-y-auto bg-surface p-0 sm:max-w-md">
        {editing && <StopForm key={editing.key} editing={editing} spots={spots} timeZone={timeZone} onSaved={onClose} />}
      </SheetContent>
    </Sheet>
  );
}

type Field = "place" | "date" | "endTime" | "slots";

function StopForm({ editing, spots, timeZone, onSaved }: { editing: StopEditing; spots: Location[]; timeZone: string; onSaved: () => void }) {
  const { draft, row, repeated } = editing;
  const isEdit = Boolean(row);
  const hasOrders = (row?.orderCount ?? 0) > 0;
  const wasLive = isEdit && row!.service.status !== "DRAFT";

  const [place, setPlace] = useState<PlaceValue | null>(() => {
    const known = [...spots, ...(row ? [row.location] : [])].find((l) => l.id === draft.locationId);
    return known ? { kind: "saved", location: known } : null;
  });
  const [date, setDate] = useState(draft.date);
  const [startTime, setStartTime] = useState(draft.startTime);
  const [endTime, setEndTime] = useState(draft.endTime);
  const [slotMinutes, setSlotMinutes] = useState(String(draft.slotMinutes));
  const [ordersPerSlot, setOrdersPerSlot] = useState(String(draft.ordersPerSlot));

  // A number that matches no preset is carried as a "custom" chip rather than silently rewritten.
  const initial = useMemo(() => {
    const opens = opensKeyFor(draft.opensHoursBefore, opensOptions(draft.date, draft.startTime, timeZone, null));
    const closes = closesKeyFor(draft.closesMinutesBefore);
    return { opens, closes, customHours: opens === "custom" ? draft.opensHoursBefore : null, customMinutes: closes === "custom" ? draft.closesMinutesBefore : null };
  }, [draft, timeZone]);
  const [opensKey, setOpensKey] = useState<OpensKey>(initial.opens);
  const [closesKey, setClosesKey] = useState<ClosesKey>(initial.closes);
  const opens = opensOptions(date, startTime, timeZone, initial.customHours);
  const closes = closesOptions(initial.customMinutes);
  const chosenOpens = opens.find((o) => o.key === opensKey) ?? opens[0];
  const chosenCloses = closes.find((o) => o.key === closesKey) ?? closes[0];

  const [result, setResult] = useState<SaveStopResult | null>(null);
  const [localError, setLocalError] = useState<{ field?: Field; error: string } | null>(null);
  const [pending, startTransition] = useTransition();

  const failure = localError ?? (result && !result.ok ? result : null);
  const fieldError = (field: Field) => (failure && "field" in failure && failure.field === field ? failure.error : null);
  const bannerError = failure && !("field" in failure && failure.field) ? failure.error : null;

  // A field error can be off-screen behind the sticky footer.
  useEffect(() => {
    if (!failure) return;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    document.querySelector("[data-field-error]")?.scrollIntoView({ block: "center", behavior: reduce ? "auto" : "smooth" });
  }, [failure]);

  const minutes = Number(slotMinutes);
  const orders = Number(ordersPerSlot);
  const summary = useMemo(() => {
    const valid = /^\d{4}-\d{2}-\d{2}$/.test(date) && /^\d{2}:\d{2}$/.test(startTime) && /^\d{2}:\d{2}$/.test(endTime) && endTime > startTime;
    if (!valid || !Number.isInteger(minutes) || !Number.isInteger(orders) || minutes < 5 || orders < 1) return null;
    return slotSummary(zonedTimeFromParts(timeZone, date, startTime), zonedTimeFromParts(timeZone, date, endTime), minutes, orders, timeZone);
  }, [date, startTime, endTime, minutes, orders, timeZone]);

  function submit(publish: boolean) {
    setResult(null);
    setLocalError(null);
    if (!place) return setLocalError({ field: "place", error: "Choose where this stop is." });
    if (!Number.isInteger(minutes) || !Number.isInteger(orders)) {
      return setLocalError({ field: "slots", error: "Enter whole numbers for how often and how many." });
    }
    startTransition(async () => {
      const saved = await saveStop({
        serviceId: row?.service.id,
        ...placeInput(place),
        date,
        startTime,
        endTime,
        opensHoursBefore: chosenOpens.hours,
        closesMinutesBefore: chosenCloses.minutes,
        slotMinutes: minutes,
        ordersPerSlot: orders,
        publicNote: draft.publicNote,
        publish,
      });
      setResult(saved);
      if (saved.ok) onSaved();
    });
  }

  const title = isEdit ? "Edit stop" : repeated ? "Repeat stop" : "Add a stop";

  return (
    <form
      // Enter in a field doesn't choose between Publish and Save as draft for you.
      onSubmit={(e) => e.preventDefault()}
      noValidate
      className="flex min-h-full flex-col"
    >
      <div className="px-5 pt-6">
        <SheetTitle className="text-[1.6rem] leading-tight font-semibold tracking-[-0.02em]">{title}</SheetTitle>
        <SheetDescription className="mt-2">
          {isEdit
            ? wasLive
              ? "Changes show on your ordering page right away."
              : "This stop is a draft. Customers can't see it yet."
            : repeated
              ? "Same as before, a few days later. Check the date, then publish."
              : "Customers can order ahead once you publish it."}
        </SheetDescription>
      </div>

      <div className="mt-6 flex-1 divide-y divide-border border-t border-border">
        <Group title="Where">
          <PlaceCombobox
            value={place}
            onChange={setPlace}
            spots={spots}
            error={fieldError("place")}
            lockedReason={hasOrders ? "This stop has orders, so its spot can't change. Cancel the stop to move it." : undefined}
          />
        </Group>

        <Group title="When" hint={`Times are in ${timeZone.replace(/_/g, " ")}.`}>
          <div>
            <label htmlFor="stop-date" className="mb-1.5 block text-sm font-semibold">
              Date
            </label>
            <input
              id="stop-date"
              type="date"
              value={date}
              onChange={(e) => setDate(e.target.value)}
              aria-invalid={Boolean(fieldError("date"))}
              aria-describedby={fieldError("date") ? "stop-date-error" : undefined}
              className={nativeInput}
            />
            <FieldError id="stop-date-error" message={fieldError("date")} />
          </div>
          <div className="mt-4 grid grid-cols-2 gap-3">
            <div>
              <label htmlFor="stop-start" className="mb-1.5 block text-sm font-semibold">
                Starts
              </label>
              <input id="stop-start" type="time" value={startTime} onChange={(e) => setStartTime(e.target.value)} className={nativeInput} />
            </div>
            <div>
              <label htmlFor="stop-end" className="mb-1.5 block text-sm font-semibold">
                Ends
              </label>
              <input
                id="stop-end"
                type="time"
                value={endTime}
                onChange={(e) => setEndTime(e.target.value)}
                aria-invalid={Boolean(fieldError("endTime"))}
                aria-describedby={fieldError("endTime") ? "stop-end-error" : undefined}
                className={nativeInput}
              />
            </div>
          </div>
          <FieldError id="stop-end-error" message={fieldError("endTime")} />
        </Group>

        <Group title="Ordering window">
          <Chips legend="Preorders open" name="opens" value={chosenOpens.key} onChange={(k) => setOpensKey(k as OpensKey)} options={opens.map((o) => ({ value: o.key, label: o.label }))} />
          <div className="mt-5">
            <Chips
              legend="Stop taking orders, before the end"
              name="closes"
              value={chosenCloses.key}
              onChange={(k) => setClosesKey(k as ClosesKey)}
              options={closes.map((o) => ({ value: o.key, label: o.label }))}
            />
          </div>
        </Group>

        <Group title="Pickup slots">
          <div className="grid grid-cols-2 gap-3">
            <NumberField id="stop-slot-minutes" label="Minutes apart" value={slotMinutes} onChange={setSlotMinutes} invalid={Boolean(fieldError("slots"))} />
            <NumberField id="stop-slot-orders" label="Orders per time" value={ordersPerSlot} onChange={setOrdersPerSlot} invalid={Boolean(fieldError("slots"))} />
          </div>
          <p aria-live="polite" className="mt-3 text-sm text-muted-foreground">
            {summary ?? "Set the times above to see how many pickup times this makes."}
          </p>
          {orders === 1 || orders === 2 ? (
            <p className="mt-1.5 text-sm font-medium text-cooking-ink">
              Only {orders} {orders === 1 ? "order" : "orders"} per pickup time. Busy stops will sell out fast.
            </p>
          ) : null}
          <FieldError id="stop-slots-error" message={fieldError("slots")} />
        </Group>
      </div>

      <div className="sticky bottom-0 border-t border-border bg-surface px-5 pt-3 pb-[max(1rem,env(safe-area-inset-bottom))]">
        <ErrorBanner message={bannerError} className="mb-3" />
        <div className="flex gap-2">
          <Button type="button" disabled={pending} onClick={() => submit(true)} className="h-12 flex-1 rounded-xl text-base font-semibold">
            {pending ? "Saving…" : wasLive ? "Save changes" : "Publish stop"}
          </Button>
          {!wasLive && (
            <Button type="button" variant="outline" disabled={pending} onClick={() => submit(false)} className="h-12 rounded-xl px-4 text-base font-semibold">
              Save as draft
            </Button>
          )}
        </div>
      </div>
    </form>
  );
}

const nativeInput =
  "h-12 w-full min-w-0 rounded-xl border border-input bg-surface px-3.5 text-base tabular-nums outline-none focus-visible:border-ring focus-visible:ring-4 focus-visible:ring-ring/40 aria-invalid:border-destructive";

function Group({ title, hint, children }: { title: string; hint?: string; children: React.ReactNode }) {
  return (
    <section className="px-5 py-6">
      <h3 className="text-[1.0625rem] font-semibold tracking-[-0.01em]">{title}</h3>
      {hint && <p className="mt-0.5 text-sm text-muted-foreground">{hint}</p>}
      <div className="mt-3.5">{children}</div>
    </section>
  );
}

function FieldError({ id, message }: { id: string; message: string | null }) {
  if (!message) return null;
  return (
    <p id={id} role="alert" data-field-error className="mt-1.5 text-sm font-medium text-destructive">
      {message}
    </p>
  );
}

function NumberField({ id, label, value, onChange, invalid }: { id: string; label: string; value: string; onChange: (v: string) => void; invalid: boolean }) {
  return (
    <TextField id={id} label={label} value={value} onChange={(v) => onChange(v.replace(/\D/g, "").slice(0, 3))} inputMode="numeric" aria-invalid={invalid} className={cn("tabular-nums")} />
  );
}

/** Radio inputs dressed as chips: native arrow-key behaviour, no ARIA to get wrong. */
function Chips({
  legend,
  name,
  value,
  onChange,
  options,
}: {
  legend: string;
  name: string;
  value: string;
  onChange: (value: string) => void;
  options: { value: string; label: string }[];
}) {
  return (
    <fieldset>
      <legend className="mb-2 text-sm font-semibold">{legend}</legend>
      <div className="flex flex-wrap gap-2">
        {options.map((o) => (
          <label key={o.value} className="relative">
            <input type="radio" name={name} value={o.value} checked={o.value === value} onChange={() => onChange(o.value)} className="peer sr-only" />
            <span className="flex h-11 cursor-pointer items-center rounded-full border border-input px-4 text-[0.9375rem] font-medium transition-colors select-none peer-checked:border-transparent peer-checked:bg-primary peer-checked:text-primary-foreground peer-focus-visible:ring-4 peer-focus-visible:ring-ring/40 motion-reduce:transition-none">
              {o.label}
            </span>
          </label>
        ))}
      </div>
    </fieldset>
  );
}

"use client";

import { useState, useTransition } from "react";
import { saveNotifications, sendTestNotification } from "@/app/(dashboard)/dashboard/(app)/settings/actions";
import { FieldRow, inputClass } from "@/components/dashboard/settings/field-row";
import { SaveRow, type SaveState } from "@/components/dashboard/settings/save-row";
import { Section } from "@/components/dashboard/settings/section";
import { useUnsavedGuard } from "@/components/dashboard/settings/use-unsaved-guard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";

type Props = {
  notificationEmail: string | null;
  notifyNewOrder: boolean;
  notifyCancellation: boolean;
  notifyDailySummary: boolean;
};

export function NotificationsForm({ notificationEmail, notifyNewOrder, notifyCancellation, notifyDailySummary }: Props) {
  const [enabled, setEnabled] = useState(notificationEmail !== null);
  const [email, setEmail] = useState(notificationEmail ?? "");
  const [events, setEvents] = useState({ notifyNewOrder, notifyCancellation, notifyDailySummary });
  const [result, setResult] = useState<SaveState>(null);
  const [testResult, setTestResult] = useState<SaveState>(null);
  const [pending, startTransition] = useTransition();
  const [testing, startTesting] = useTransition();

  const dirty =
    enabled !== (notificationEmail !== null) ||
    (enabled &&
      (email.trim() !== (notificationEmail ?? "") ||
        events.notifyNewOrder !== notifyNewOrder ||
        events.notifyCancellation !== notifyCancellation ||
        events.notifyDailySummary !== notifyDailySummary));
  useUnsavedGuard(dirty);

  function submit(e: React.FormEvent) {
    e.preventDefault();
    startTransition(async () => setResult(await saveNotifications({ enabled, email, ...events })));
  }

  function setEvent(key: keyof typeof events) {
    return (checked: boolean) => {
      setEvents((prev) => ({ ...prev, [key]: checked }));
      setResult(null);
    };
  }

  // The test goes to the saved address (what orders really use), so it needs a saved one and no pending edits.
  const canTest = notificationEmail !== null && !dirty && !pending && !testing;

  return (
    <form onSubmit={submit} noValidate>
      <Section title="Notifications" description="How we tell you what's happening with your orders.">
        <FieldRow label="Order emails" htmlFor="notify-enabled">
          <div className="flex h-12 items-center gap-3">
            <Switch
              id="notify-enabled"
              disabled={pending}
              checked={enabled}
              onCheckedChange={(checked) => {
                setEnabled(checked);
                setResult(null);
                setTestResult(null);
                // Turning off saves right away (a switch that needs a Save button lies).
                // Turning on waits for an address.
                if (!checked) startTransition(async () => setResult(await saveNotifications({ enabled: false, email, ...events })));
              }}
            />
            <span className="text-base">{enabled ? "On" : "Off"}</span>
          </div>
        </FieldRow>
        {enabled && (
          <>
            <FieldRow label="Email address" htmlFor="notify-email" hint="One address for everything below.">
              <Input
                id="notify-email"
                type="email"
                autoComplete="email"
                value={email}
                onChange={(e) => {
                  setEmail(e.target.value);
                  setResult(null);
                  setTestResult(null);
                }}
                placeholder="you@yourtruck.com"
                aria-invalid={result !== null && !result.ok}
                className={inputClass}
              />
            </FieldRow>
            <EventRow id="notify-new-order" label="New orders" hint="Every time an online order comes in." checked={events.notifyNewOrder} onChange={setEvent("notifyNewOrder")} />
            <EventRow
              id="notify-cancellation"
              label="Cancellations"
              hint="Saved, but these emails aren't sent yet."
              checked={events.notifyCancellation}
              onChange={setEvent("notifyCancellation")}
            />
            <EventRow
              id="notify-daily"
              label="Daily summary"
              hint="Saved, but these emails aren't sent yet."
              checked={events.notifyDailySummary}
              onChange={setEvent("notifyDailySummary")}
            />
            <FieldRow
              label="Test"
              hint={
                notificationEmail === null
                  ? "Save an address to send a test."
                  : dirty
                    ? "Save your changes first. The test goes to the saved address."
                    : `Sends a test to ${notificationEmail}, so you know orders will reach you.`
              }
            >
              <Button
                type="button"
                variant="secondary"
                disabled={!canTest}
                onClick={() => {
                  setTestResult(null);
                  startTesting(async () => setTestResult(await sendTestNotification()));
                }}
                className="h-11 rounded-xl px-5 text-base font-semibold"
              >
                {testing ? "Sending…" : "Send test email"}
              </Button>
              {testResult && (
                <p role="status" className={testResult.ok ? "mt-2 text-sm text-ok" : "mt-2 text-sm font-medium text-destructive"}>
                  {testResult.ok ? (testResult.note ?? "Sent.") : testResult.error}
                </p>
              )}
            </FieldRow>
          </>
        )}
        <SaveRow
          dirty={dirty}
          pending={pending}
          result={result}
          successText={enabled ? "Saved. Order emails will go to this address." : "Saved. Order emails are off."}
        />
      </Section>
    </form>
  );
}

function EventRow({ id, label, hint, checked, onChange }: { id: string; label: string; hint: string; checked: boolean; onChange: (checked: boolean) => void }) {
  return (
    <FieldRow label={label} htmlFor={id} hint={hint}>
      <div className="flex h-12 items-center gap-3">
        <Switch id={id} checked={checked} onCheckedChange={onChange} />
        <span className="text-base">{checked ? "On" : "Off"}</span>
      </div>
    </FieldRow>
  );
}

