"use client";

import { useState, useTransition } from "react";
import { inviteMember, removeMember, resendInvite, revokePendingInvite, saveMemberRole } from "@/app/(dashboard)/dashboard/(app)/settings/actions";
import { FieldRow, inputClass } from "@/components/dashboard/settings/field-row";
import { SaveRow, type SaveState } from "@/components/dashboard/settings/save-row";
import { Section } from "@/components/dashboard/settings/section";
import { useUnsavedGuard } from "@/components/dashboard/settings/use-unsaved-guard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import type { PendingInvite, TeamMember } from "@/lib/types";

const ROLE_LABELS = { OWNER: "Owner", STAFF: "Staff" } as const;

type Props = {
  members: TeamMember[];
  invites: PendingInvite[];
  currentUserId: string;
  timezone: string;
  appUrl: string;
};

export function TeamList({ members, invites, currentUserId, timezone, appUrl }: Props) {
  const [error, setError] = useState<string | null>(null);
  const [confirmingId, setConfirmingId] = useState<string | null>(null);
  const [inviteResult, setInviteResult] = useState<Record<string, SaveState>>({});
  const [pending, startTransition] = useTransition();

  function run(action: () => ReturnType<typeof removeMember>) {
    setError(null);
    startTransition(async () => {
      const result = await action();
      if (!result.ok) setError(result.error);
      else setConfirmingId(null);
    });
  }

  function runInvite(inviteId: string, action: () => Promise<NonNullable<SaveState>>) {
    setError(null);
    startTransition(async () => {
      const result = await action();
      setInviteResult((prev) => ({ ...prev, [inviteId]: result }));
      setConfirmingId(null);
    });
  }

  const formatDate = (iso: string) =>
    new Intl.DateTimeFormat("en-US", { timeZone: timezone, month: "short", day: "numeric", year: "numeric" }).format(new Date(iso));

  return (
    <div className="space-y-6">
      <Section title="Team" description="Everyone who can sign in to this truck's dashboard.">
        {members.map((member) => {
          const isYou = member.clerkUserId === currentUserId;
          // Older members have no stored email, so fall back to a piece of their id.
          const name = member.email ?? `Member ${member.clerkUserId.slice(-6)}`;
          return (
            <div key={member.id} className="px-5 py-4">
              <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
                <div className="min-w-0 flex-1 basis-48">
                  <p className="truncate text-base font-medium">{isYou ? "You" : name}</p>
                  <p className="truncate text-sm text-muted-foreground">
                    {isYou && member.email ? `${member.email} · ` : ""}
                    {ROLE_LABELS[member.role]} · joined {formatDate(member.joinedAt)}
                  </p>
                </div>
                {!isYou && (
                  <div className="flex gap-2">
                    <Button
                      type="button"
                      variant="secondary"
                      disabled={pending}
                      onClick={() => run(() => saveMemberRole({ membershipId: member.id, role: member.role === "OWNER" ? "STAFF" : "OWNER" }))}
                      className="h-11 rounded-xl px-4 text-sm font-semibold"
                    >
                      {member.role === "OWNER" ? "Make staff" : "Make owner"}
                    </Button>
                    <Button
                      type="button"
                      variant="ghost"
                      disabled={pending}
                      onClick={() => setConfirmingId(confirmingId === member.id ? null : member.id)}
                      className="h-11 rounded-xl px-4 text-sm font-semibold text-destructive hover:text-destructive"
                    >
                      Remove
                    </Button>
                  </div>
                )}
              </div>
              {confirmingId === member.id && (
                <div role="alertdialog" aria-label="Confirm removal" className="mt-3 border-t border-border pt-3">
                  <p className="text-sm">They will lose access to this dashboard right away.</p>
                  <div className="mt-2 flex gap-2">
                    <Button type="button" variant="destructive" disabled={pending} onClick={() => run(() => removeMember(member.id))} className="h-11 rounded-xl px-5 text-sm font-semibold">
                      {pending ? "Removing…" : "Remove member"}
                    </Button>
                    <Button type="button" variant="ghost" onClick={() => setConfirmingId(null)} className="h-11 rounded-xl px-4 text-sm">
                      Cancel
                    </Button>
                  </div>
                </div>
              )}
            </div>
          );
        })}
        {error && (
          <p role="alert" className="px-5 py-3 text-sm font-medium text-destructive">
            {error}
          </p>
        )}
      </Section>

      {invites.length > 0 && (
        <Section title="Pending invites" description="They join as soon as they open the link and sign in.">
          {invites.map((invite) => {
            const result = inviteResult[invite.id] ?? null;
            const key = `invite:${invite.id}`;
            return (
              <div key={invite.id} className="px-5 py-4">
                <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
                  <div className="min-w-0 flex-1 basis-48">
                    <p className="truncate text-base font-medium">{invite.email}</p>
                    <p className={invite.expired ? "text-sm font-medium text-destructive" : "text-sm text-muted-foreground"}>
                      {ROLE_LABELS[invite.role]} · {invite.expired ? "expired" : "expires"} {formatDate(invite.expiresAt)}
                    </p>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    <Button
                      type="button"
                      variant="secondary"
                      disabled={pending}
                      onClick={() => runInvite(invite.id, () => resendInvite(invite.id))}
                      className="h-11 rounded-xl px-4 text-sm font-semibold"
                    >
                      Resend
                    </Button>
                    <CopyLinkButton url={`${appUrl}/invite/${invite.token}`} disabled={pending || invite.expired} />
                    <Button
                      type="button"
                      variant="ghost"
                      disabled={pending}
                      onClick={() => setConfirmingId(confirmingId === key ? null : key)}
                      className="h-11 rounded-xl px-4 text-sm font-semibold text-destructive hover:text-destructive"
                    >
                      Revoke
                    </Button>
                  </div>
                </div>
                {confirmingId === key && (
                  <div role="alertdialog" aria-label="Confirm revoking the invite" className="mt-3 border-t border-border pt-3">
                    <p className="text-sm">The link in their email will stop working.</p>
                    <div className="mt-2 flex gap-2">
                      <Button
                        type="button"
                        variant="destructive"
                        disabled={pending}
                        onClick={() => runInvite(invite.id, async () => {
                          const done = await revokePendingInvite(invite.id);
                          return done.ok ? { ok: true as const, note: "Revoked." } : done;
                        })}
                        className="h-11 rounded-xl px-5 text-sm font-semibold"
                      >
                        {pending ? "Revoking…" : "Revoke invite"}
                      </Button>
                      <Button type="button" variant="ghost" onClick={() => setConfirmingId(null)} className="h-11 rounded-xl px-4 text-sm">
                        Cancel
                      </Button>
                    </div>
                  </div>
                )}
                {result && (
                  <p role="status" className={result.ok ? "mt-2 text-sm text-ok" : "mt-2 text-sm font-medium text-destructive"}>
                    {result.ok ? (result.note ?? "Done.") : result.error}
                  </p>
                )}
              </div>
            );
          })}
        </Section>
      )}

      <InviteForm />
    </div>
  );
}

function InviteForm() {
  const [email, setEmail] = useState("");
  const [role, setRole] = useState<"OWNER" | "STAFF">("STAFF");
  const [result, setResult] = useState<SaveState>(null);
  const [pending, startTransition] = useTransition();

  const dirty = email.trim() !== "";
  useUnsavedGuard(dirty);

  function submit(e: React.FormEvent) {
    e.preventDefault();
    startTransition(async () => {
      const sent = await inviteMember({ email, role });
      setResult(sent);
      if (sent.ok) setEmail("");
    });
  }

  return (
    <form onSubmit={submit} noValidate>
      <Section title="Invite someone" description="We email them a link that works for 7 days.">
        <FieldRow label="Email" htmlFor="invite-email">
          <Input
            id="invite-email"
            type="email"
            autoComplete="off"
            value={email}
            onChange={(e) => {
              setEmail(e.target.value);
              setResult(null);
            }}
            placeholder="sam@example.com"
            aria-invalid={result !== null && !result.ok}
            className={inputClass}
          />
        </FieldRow>
        <FieldRow label="Role" htmlFor="invite-role" hint={role === "OWNER" ? "Owners can change every setting and manage the team." : "Staff can work orders, the menu and the schedule."}>
          <select
            id="invite-role"
            value={role}
            onChange={(e) => {
              setRole(e.target.value as "OWNER" | "STAFF");
              setResult(null);
            }}
            className={`${inputClass} w-full border border-input bg-transparent`}
          >
            <option value="STAFF">Staff</option>
            <option value="OWNER">Owner</option>
          </select>
        </FieldRow>
        <SaveRow dirty={dirty} pending={pending} result={result} label="Send invite" successText="Invite sent." />
      </Section>
    </form>
  );
}

function CopyLinkButton({ url, disabled }: { url: string; disabled: boolean }) {
  const [copied, setCopied] = useState<"yes" | "no" | null>(null);

  return (
    <Button
      type="button"
      variant="ghost"
      disabled={disabled}
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(url);
          setCopied("yes");
        } catch {
          setCopied("no"); // clipboard blocked: the link is still on the invite email
        }
        setTimeout(() => setCopied(null), 2500);
      }}
      className="h-11 rounded-xl px-4 text-sm font-semibold"
    >
      {copied === "yes" ? "Copied" : copied === "no" ? "Couldn't copy" : "Copy link"}
    </Button>
  );
}

"use client";

import { useState } from "react";
import { cn } from "@/lib/utils";

type Props = {
  src: string | null | undefined;
  /** Empty for a thumbnail that sits next to the item's name (the name already says it). */
  alt: string;
  className?: string;
};

/**
 * A menu item photo in a fixed-shape box, so the page doesn't jump while it
 * loads. Renders nothing when the item has no photo or the image fails to load,
 * so the row just reads as text.
 */
export function ItemPhoto({ src, alt, className }: Props) {
  const [failed, setFailed] = useState(false);
  if (!src || failed) return null;

  return (
    <div className={cn("overflow-hidden bg-muted", className)}>
      {/* Plain <img>: vendors can host photos anywhere, so next/image would need every domain listed. */}
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={src}
        alt={alt}
        loading="lazy"
        decoding="async"
        onError={() => setFailed(true)}
        className="size-full object-cover"
      />
    </div>
  );
}

"use client";

import { useState } from "react";
import { Minus, Plus } from "lucide-react";
import type { MenuItem, ModifierGroup } from "@/lib/types";
import { formatCents, unitPriceCents } from "@/lib/money";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Sheet, SheetContent, SheetDescription, SheetTitle } from "@/components/ui/sheet";
import { useCart } from "@/components/storefront/cart-provider";
import { ItemPhoto } from "@/components/storefront/item-photo";

type Props = {
  item: MenuItem | null;
  canOrder: boolean;
  closedReason: string | null;
  onClose: () => void;
};

export function ItemSheet({ item, canOrder, closedReason, onClose }: Props) {
  // Keep showing the last item while the sheet animates closed.
  const [shown, setShown] = useState<MenuItem | null>(item);
  if (item && item !== shown) setShown(item);

  return (
    <Sheet open={item !== null} onOpenChange={(open) => !open && onClose()}>
      <SheetContent
        side="bottom"
        className="mx-auto max-h-[92dvh] w-full max-w-2xl gap-0 rounded-t-3xl border-0 bg-surface p-0"
      >
        {shown && (
          <ItemSheetBody key={shown.id} item={shown} canOrder={canOrder} closedReason={closedReason} onAdded={onClose} />
        )}
      </SheetContent>
    </Sheet>
  );
}

type Selections = Record<string, string[]>; // groupId → chosen option ids

function defaultSelections(item: MenuItem): Selections {
  // Pre-pick the first available option for required single-choice groups.
  // One less tap for the common case, still easy to change.
  const picks: Selections = {};
  for (const group of item.modifierGroups) {
    const first = group.options.find((o) => o.isAvailable);
    picks[group.id] = group.required && group.maxSelect === 1 && first ? [first.id] : [];
  }
  return picks;
}

function ItemSheetBody({
  item,
  canOrder,
  closedReason,
  onAdded,
}: {
  item: MenuItem;
  canOrder: boolean;
  closedReason: string | null;
  onAdded: () => void;
}) {
  const { add } = useCart();
  const [selections, setSelections] = useState<Selections>(() => defaultSelections(item));
  const [quantity, setQuantity] = useState(1);

  const optionIds = Object.values(selections).flat();
  const unmet = item.modifierGroups.find((g) => (selections[g.id]?.length ?? 0) < g.minSelect);
  const totalCents = unitPriceCents(item, optionIds) * quantity;

  function handleAdd() {
    if (unmet || !canOrder) return;
    add(item.id, optionIds, quantity);
    onAdded();
  }

  return (
    <>
      <div className="overflow-y-auto pb-4">
        <div aria-hidden className="mx-auto mt-3 mb-4 h-1 w-10 rounded-full bg-border" />
        {/* Full-bleed: the dish is the first thing you see. ItemPhoto renders
            nothing when there is no photo, so the sheet just opens on the name. */}
        <ItemPhoto src={item.imageUrl} alt="" className="aspect-[16/9] w-full" />

        <div className="px-5 pt-5">
          <SheetTitle className="pr-8 font-display text-[1.875rem] leading-[1.05] font-bold">{item.name}</SheetTitle>
          {item.description && (
            <SheetDescription className="mt-2 text-[0.9375rem] leading-relaxed">{item.description}</SheetDescription>
          )}
          <p className="mt-2 font-medium tabular-nums">{formatCents(item.priceCents)}</p>

          {item.modifierGroups.map((group) => (
            <ModifierGroupField
              key={group.id}
              group={group}
              value={selections[group.id] ?? []}
              onChange={(ids) => setSelections((s) => ({ ...s, [group.id]: ids }))}
            />
          ))}
        </div>
      </div>

      <div className="border-t border-border bg-surface px-5 pt-3 pb-[max(1rem,env(safe-area-inset-bottom))]">
        {!canOrder && closedReason && <p className="mb-3 text-sm text-muted-foreground">{closedReason}</p>}
        {canOrder && unmet && (
          <p className="mb-3 text-sm text-muted-foreground">Choose a {unmet.name.toLowerCase()} to continue.</p>
        )}
        <div className="flex items-center gap-3">
          <div className="flex h-12 items-center rounded-xl ring-1 ring-border">
            <button
              type="button"
              aria-label="Remove one"
              onClick={() => setQuantity((q) => Math.max(1, q - 1))}
              disabled={quantity <= 1}
              className="flex size-12 items-center justify-center rounded-l-xl outline-none focus-visible:ring-2 focus-visible:ring-brand disabled:opacity-40"
            >
              <Minus className="size-4" />
            </button>
            <span aria-live="polite" className="w-6 text-center font-semibold tabular-nums">
              {quantity}
            </span>
            <button
              type="button"
              aria-label="Add one"
              onClick={() => setQuantity((q) => Math.min(20, q + 1))}
              className="flex size-12 items-center justify-center rounded-r-xl outline-none focus-visible:ring-2 focus-visible:ring-brand"
            >
              <Plus className="size-4" />
            </button>
          </div>
          <Button
            onClick={handleAdd}
            disabled={!canOrder || Boolean(unmet)}
            className="h-12 flex-1 justify-between rounded-xl px-5 text-base font-semibold"
          >
            <span>Add to order</span>
            <span className="tabular-nums">{formatCents(totalCents)}</span>
          </Button>
        </div>
      </div>
    </>
  );
}

function requirementText(group: ModifierGroup): string {
  if (group.required && group.maxSelect === 1) return "Required";
  if (group.required) return `Required, pick ${group.minSelect}–${group.maxSelect}`;
  return group.maxSelect === 1 ? "Optional" : `Optional, up to ${group.maxSelect}`;
}

function ModifierGroupField({
  group,
  value,
  onChange,
}: {
  group: ModifierGroup;
  value: string[];
  onChange: (ids: string[]) => void;
}) {
  const single = group.maxSelect === 1;
  const atMax = value.length >= group.maxSelect;

  return (
    <fieldset className="mt-7">
      <legend className="flex w-full items-baseline justify-between gap-4">
        <span className="font-display text-xl font-semibold">{group.name}</span>
        <span className="text-sm text-muted-foreground">{requirementText(group)}</span>
      </legend>

      <div className="mt-2 divide-y divide-border">
        {single ? (
          <RadioGroup value={value[0] ?? null} onValueChange={(v) => onChange(v ? [v as string] : [])} className="gap-0">
            {group.options.map((option) => (
              <OptionRow key={option.id} name={option.name} priceDeltaCents={option.priceDeltaCents} soldOut={!option.isAvailable}>
                <RadioGroupItem value={option.id} disabled={!option.isAvailable} />
              </OptionRow>
            ))}
          </RadioGroup>
        ) : (
          group.options.map((option) => {
            const checked = value.includes(option.id);
            return (
              <OptionRow key={option.id} name={option.name} priceDeltaCents={option.priceDeltaCents} soldOut={!option.isAvailable}>
                <Checkbox
                  checked={checked}
                  disabled={!option.isAvailable || (!checked && atMax)}
                  onCheckedChange={(next) =>
                    onChange(next ? [...value, option.id] : value.filter((id) => id !== option.id))
                  }
                />
              </OptionRow>
            );
          })
        )}
      </div>
    </fieldset>
  );
}

function OptionRow({
  name,
  priceDeltaCents,
  soldOut,
  children,
}: {
  name: string;
  priceDeltaCents: number;
  soldOut: boolean;
  children: React.ReactNode;
}) {
  return (
    <label className={cn("flex min-h-12 cursor-pointer items-center gap-3 py-2", soldOut && "cursor-not-allowed text-muted-foreground")}>
      {children}
      <span className="flex-1">{name}</span>
      <span className="text-sm tabular-nums text-muted-foreground">
        {soldOut ? "Sold out" : priceDeltaCents > 0 ? `+${formatCents(priceDeltaCents)}` : null}
      </span>
    </label>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { Minus, Plus, Search, Trash2 } from "lucide-react";
import type { Menu, MenuItem } from "@/lib/types";
import { lineKey } from "@/lib/cart";
import { formatCents } from "@/lib/money";
import { cn } from "@/lib/utils";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { useCart } from "@/components/storefront/cart-provider";
import { ItemPhoto } from "@/components/storefront/item-photo";
import { ItemSheet } from "@/components/storefront/item-sheet";

// Where a section counts as "the one you're in": just under the sticky chip bar,
// in the top third of the screen.
const SPY_ROOT_MARGIN = "-72px 0px -65% 0px";

type Props = {
  menu: Menu;
  canOrder: boolean;
  closedReason: string | null; // shown in the item sheet when ordering isn't open
};

export function MenuList({ menu, canOrder, closedReason }: Props) {
  const [openItem, setOpenItem] = useState<MenuItem | null>(null);
  const [query, setQuery] = useState("");
  const [hideSoldOut, setHideSoldOut] = useState(false);

  // Filter what's already on the page. Sold-out items show by default (hiding
  // them makes customers think the menu changed), so hiding is opt-in.
  const needle = query.trim().toLowerCase();
  const sections = menu.sections
    .map((section) => ({
      ...section,
      items: section.items.filter(
        (item) =>
          (!hideSoldOut || item.isAvailable) &&
          (!needle || `${item.name} ${item.description}`.toLowerCase().includes(needle))
      ),
    }))
    .filter((section) => section.items.length > 0);
  const filtering = needle !== "" || hideSoldOut;
  const matchCount = sections.reduce((sum, section) => sum + section.items.length, 0);

  // Highlight the chip for the section on screen, and keep it in view in the chip row.
  const [activeId, setActiveId] = useState<string | null>(null);
  const chipListRef = useRef<HTMLUListElement>(null);
  const sectionKey = sections.map((s) => s.id).join(",");
  const currentId = sections.some((s) => s.id === activeId) ? activeId : (sections[0]?.id ?? null);

  // A tapped chip stays highlighted until the customer scrolls on their own. Without this, the last
  // sections (which can't scroll up to the top of the screen) would hand the highlight to the section above.
  const pinnedRef = useRef<string | null>(null);
  const userScrolledRef = useRef(false);

  useEffect(() => {
    if (!sectionKey || typeof IntersectionObserver === "undefined") return;
    const ids = sectionKey.split(",");
    const inBand = new Set<string>();
    pinnedRef.current = null; // the list changed (search/filter), so start following the scroll again
    // The topmost section in the band wins, so the chip changes as a heading reaches the bar.
    const follow = () => {
      const first = ids.find((id) => inBand.has(id));
      if (first) setActiveId(first);
    };
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) inBand.add(entry.target.id);
          else inBand.delete(entry.target.id);
        }
        if (!pinnedRef.current) follow();
      },
      { rootMargin: SPY_ROOT_MARGIN }
    );
    for (const id of ids) {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    }

    // The customer's own wheel, touch, key or scrollbar drag ends the pin; the next scroll hands control back.
    const noteUserInput = (event: Event) => {
      if (event.target instanceof Element && event.target.closest("[data-chip]")) return;
      userScrolledRef.current = true;
    };
    const onScroll = () => {
      if (pinnedRef.current && userScrolledRef.current) {
        pinnedRef.current = null;
        follow();
      }
    };
    const inputEvents = ["wheel", "touchmove", "keydown", "pointerdown"] as const;
    for (const name of inputEvents) window.addEventListener(name, noteUserInput, { passive: true });
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => {
      observer.disconnect();
      for (const name of inputEvents) window.removeEventListener(name, noteUserInput);
      window.removeEventListener("scroll", onScroll);
    };
  }, [sectionKey]);

  useEffect(() => {
    const list = chipListRef.current;
    if (!list || !currentId) return;
    const chip = list.querySelector<HTMLElement>(`[data-chip="${CSS.escape(currentId)}"]`);
    if (!chip) return;
    const offset =
      chip.getBoundingClientRect().left - list.getBoundingClientRect().left - (list.clientWidth - chip.offsetWidth) / 2;
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    list.scrollBy({ left: offset, behavior: reduceMotion ? "auto" : "smooth" });
  }, [currentId]);

  // A stop can be published before the vendor has added anything to its menu.
  if (menu.sections.length === 0) {
    return (
      <section id="menu" aria-labelledby="menu-heading" className="scroll-mt-4 pt-10">
        <div className="mx-auto max-w-2xl md:max-w-3xl lg:max-w-4xl px-4">
          <h2 id="menu-heading" className="font-display text-[1.75rem] leading-tight font-bold">
            Menu
          </h2>
          <div className="mt-3 rounded-2xl bg-surface px-5 py-8">
            <p className="font-semibold">The menu isn&apos;t up yet.</p>
            <p className="mt-1 text-sm text-muted-foreground">
              The truck hasn&apos;t added items for this stop. Check back soon, or come see what&apos;s on at the window.
            </p>
          </div>
        </div>
      </section>
    );
  }

  return (
    <section id="menu" aria-labelledby="menu-heading" className="scroll-mt-4 pt-10">
      <div className="mx-auto max-w-2xl md:max-w-3xl lg:max-w-4xl px-4">
        <h2 id="menu-heading" className="font-display text-[1.75rem] leading-tight font-bold">
          Menu
        </h2>

        <div role="search" className="mt-3 space-y-3">
          <div className="relative">
            <label htmlFor="menu-search" className="sr-only">
              Search the menu
            </label>
            <Search aria-hidden className="pointer-events-none absolute top-1/2 left-3.5 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              id="menu-search"
              type="search"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search the menu"
              autoComplete="off"
              className="h-12 rounded-xl bg-surface pr-3.5 pl-10 text-base"
            />
          </div>
          <label className="flex min-h-10 cursor-pointer items-center gap-3 text-sm">
            <Checkbox checked={hideSoldOut} onCheckedChange={(next) => setHideSoldOut(next === true)} />
            Hide sold out items
          </label>
          <p role="status" className="sr-only">
            {filtering ? `${matchCount} ${matchCount === 1 ? "item" : "items"} shown.` : ""}
          </p>
        </div>
      </div>

      {sections.length > 0 && (
        <nav
          aria-label="Menu sections"
          className="sticky top-0 z-20 mt-2 border-b border-border bg-background/95 backdrop-blur supports-backdrop-filter:bg-background/80"
        >
          <ul
            ref={chipListRef}
            className="no-scrollbar mx-auto flex max-w-2xl md:max-w-3xl lg:max-w-4xl gap-2 overflow-x-auto px-4 py-2.5"
          >
            {sections.map((section) => {
              const current = section.id === currentId;
              return (
                <li key={section.id}>
                  <a
                    href={`#${section.id}`}
                    data-chip={section.id}
                    aria-current={current ? "location" : undefined}
                    onClick={() => {
                      pinnedRef.current = section.id;
                      userScrolledRef.current = false;
                      setActiveId(section.id);
                    }}
                    className={cn(
                      "inline-flex h-9 items-center rounded-full px-4 text-sm font-medium whitespace-nowrap ring-1 outline-none transition-colors focus-visible:ring-2 focus-visible:ring-brand",
                      current
                        ? "bg-brand text-brand-foreground ring-brand"
                        : "bg-surface ring-border hover:ring-foreground/30"
                    )}
                  >
                    {section.name}
                  </a>
                </li>
              );
            })}
          </ul>
        </nav>
      )}

      <div className="mx-auto max-w-2xl md:max-w-3xl lg:max-w-4xl px-4">
        {sections.length === 0 && (
          <div className="mt-7 rounded-2xl bg-surface px-5 py-8">
            <p className="font-semibold">Nothing matches.</p>
            <p className="mt-1 text-sm text-muted-foreground">
              Try a different word, or show sold out items again.
            </p>
            <button
              type="button"
              onClick={() => {
                setQuery("");
                setHideSoldOut(false);
              }}
              className="mt-4 font-semibold text-brand underline underline-offset-4 outline-none focus-visible:rounded-sm focus-visible:ring-2 focus-visible:ring-brand focus-visible:ring-offset-2"
            >
              Clear search
            </button>
          </div>
        )}
        {sections.map((section) => (
          <div key={section.id} id={section.id} className="scroll-mt-16 pt-7">
            <h3 className="font-display text-[1.375rem] leading-tight font-semibold">{section.name}</h3>
            <ul className="mt-3 divide-y divide-border overflow-hidden rounded-2xl bg-surface md:grid md:grid-cols-2 md:gap-3 md:divide-y-0 md:overflow-visible md:rounded-none md:bg-transparent">
              {section.items.map((item) => (
                <li key={item.id} className="md:overflow-hidden md:rounded-2xl md:bg-surface">
                  <MenuRow item={item} canOrder={canOrder} onSelect={() => setOpenItem(item)} />
                </li>
              ))}
            </ul>
          </div>
        ))}
      </div>

      <ItemSheet
        item={openItem}
        canOrder={canOrder}
        closedReason={closedReason}
        onClose={() => setOpenItem(null)}
      />
    </section>
  );
}

// Sold-out items stay in place, visibly disabled. Hiding them makes customers
// think the menu changed.
function MenuRow({ item, canOrder, onSelect }: { item: MenuItem; canOrder: boolean; onSelect: () => void }) {
  const soldOut = !item.isAvailable;
  const { lines, add, setQuantity } = useCart();

  // An item with nothing to choose can be added with one tap, right from the menu.
  // Items with options still open the sheet, because there is something to decide.
  const hasOptions = item.modifierGroups.length > 0;
  const showControl = !soldOut && canOrder;
  const key = lineKey(item.id, []);
  const quantity = !hasOptions ? (lines.find((l) => l.key === key)?.quantity ?? 0) : 0;

  return (
    <div className={cn("flex items-start", !soldOut && "hover:bg-muted/60 active:bg-muted")}>
      <button
        type="button"
        onClick={onSelect}
        disabled={soldOut}
        className={cn(
          "flex min-w-0 flex-1 items-start gap-4 py-4 pl-4 text-left outline-none focus-visible:bg-muted",
          showControl ? "pr-3" : "pr-4"
        )}
      >
        <div className="min-w-0 flex-1">
          <p className={cn("font-semibold", soldOut && "text-muted-foreground")}>{item.name}</p>
          {item.description && (
            <p className={cn("mt-1 line-clamp-2 text-sm leading-snug text-muted-foreground", soldOut && "opacity-70")}>
              {item.description}
            </p>
          )}
          <p className="mt-2 text-sm font-medium tabular-nums">
            {soldOut ? (
              <span className="text-muted-foreground">
                <span className="line-through">{formatCents(item.priceCents)}</span>
                <span className="ml-2 no-underline">Sold out today</span>
              </span>
            ) : (
              formatCents(item.priceCents)
            )}
          </p>
        </div>
        <ItemPhoto
          src={item.imageUrl}
          alt=""
          className={cn("size-16 shrink-0 rounded-xl", soldOut && "opacity-50 grayscale")}
        />
      </button>

      {showControl && (
        <div className="shrink-0 py-4 pr-4">
          {hasOptions ? (
            <RoundButton label={`Choose options for ${item.name}`} onClick={onSelect}>
              <Plus className="size-4.5" strokeWidth={2.5} />
            </RoundButton>
          ) : quantity === 0 ? (
            <RoundButton label={`Add ${item.name} to order`} onClick={() => add(item.id, [], 1)}>
              <Plus className="size-4.5" strokeWidth={2.5} />
            </RoundButton>
          ) : (
            <div className="flex h-9 items-center rounded-full text-brand ring-1 ring-brand/40">
              <StepperButton
                label={quantity === 1 ? `Remove ${item.name}` : `One less ${item.name}`}
                onClick={() => setQuantity(key, quantity - 1)}
              >
                {quantity === 1 ? <Trash2 className="size-4" /> : <Minus className="size-4" />}
              </StepperButton>
              <span aria-live="polite" className="w-5 text-center text-sm font-semibold text-foreground tabular-nums">
                {quantity}
              </span>
              <StepperButton
                label={`One more ${item.name}`}
                onClick={() => setQuantity(key, Math.min(20, quantity + 1))}
                disabled={quantity >= 20}
              >
                <Plus className="size-4" />
              </StepperButton>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// The "+" on a menu row. The visible circle is 36px; the invisible ring around it
// makes the tap target 48px, the size thumbs need.
function RoundButton({ label, onClick, children }: { label: string; onClick: () => void; children: React.ReactNode }) {
  return (
    <button
      type="button"
      aria-label={label}
      onClick={onClick}
      className="relative flex size-9 items-center justify-center rounded-full text-brand ring-1 ring-brand/40 outline-none after:absolute after:-inset-1.5 after:content-[''] hover:bg-brand/10 focus-visible:ring-2 focus-visible:ring-brand active:bg-brand/20"
    >
      {children}
    </button>
  );
}

function StepperButton({
  label,
  onClick,
  disabled,
  children,
}: {
  label: string;
  onClick: () => void;
  disabled?: boolean;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      aria-label={label}
      onClick={onClick}
      disabled={disabled}
      className="relative flex size-9 items-center justify-center rounded-full outline-none after:absolute after:-inset-0.5 after:content-[''] hover:bg-brand/10 focus-visible:ring-2 focus-visible:ring-brand disabled:opacity-40"
    >
      {children}
    </button>
  );
}

import Link from "next/link";
import { Check } from "lucide-react";
import type { Location, OrderStatus as Status, OrderView, Truck } from "@/lib/types";
import { formatCents } from "@/lib/money";
import { directionsUrl } from "@/lib/service";
import { formatDayLabel, formatTime } from "@/lib/time";
import { cn } from "@/lib/utils";
import { OrderActions } from "@/components/storefront/order-actions";
import { RefreshStatus } from "@/components/storefront/refresh-status";

// Customer-facing progress, in the order it happens. Each kitchen status gets
// its own step; ACCEPTED is legacy and shares the "Being prepared" step.
const STEPS: { label: string; statuses: Status[] }[] = [
  { label: "Order sent", statuses: ["PAID"] },
  { label: "Being prepared", statuses: ["ACCEPTED", "PREPARING"] },
  { label: "Ready at the window", statuses: ["READY"] },
  { label: "Picked up", statuses: ["PICKED_UP"] },
];

// The one line under the truck name: this is what changes when the truck taps Accept.
const HEADLINE: Partial<Record<Status, (name: string) => string>> = {
  PAID: (n) => `Thanks, ${n}. Waiting for the truck to confirm.`,
  ACCEPTED: (n) => `${n}, the truck has your order — it's being made.`,
  PREPARING: (n) => `${n}, the truck has your order — it's being made.`,
  READY: (n) => `${n}, your order is ready.`,
  PICKED_UP: (n) => `Thanks, ${n}. Enjoy.`,
};

type Props = {
  truck: Truck;
  order: OrderView;
  location: Location;
  /** Set while the page is polling, so the customer can see how fresh the status is. */
  refresh?: { renderedAt: string; seconds: number };
};

export function OrderStatus({ truck, order, location, refresh }: Props) {
  const tz = truck.timezone;
  const cancelled = order.status === "CANCELLED" || order.status === "REFUNDED";
  const current = STEPS.findIndex((s) => s.statuses.includes(order.status));
  const headline = HEADLINE[order.status]?.(order.customerName) ?? `Thanks, ${order.customerName}.`;

  return (
    <main className="mx-auto max-w-2xl pb-16 md:max-w-3xl lg:max-w-4xl">
      {/* The page refreshes itself while the order is active. This tells screen reader users when the status moves. */}
      <p role="status" className="sr-only">
        {cancelled ? "Order cancelled." : current >= 0 ? `Order status: ${STEPS[current].label}.` : ""}
      </p>
      <section className="bg-brand px-4 pt-8 pb-8 text-brand-foreground sm:rounded-b-3xl">
        <p className="font-display text-xl font-bold tracking-wide">{truck.name}</p>
        <p className="mt-8 text-base font-medium">{headline}</p>
        <p className="mt-1 text-[0.9375rem] opacity-90">Your order number is</p>
        <h1 className="font-display text-[clamp(6rem,34vw,10rem)] leading-[0.85] font-extrabold tabular-nums">
          {order.orderNumber}
        </h1>
        <p className="mt-3 text-[0.9375rem] opacity-90">Show this number at the pickup window.</p>
      </section>

      <div className="md:grid md:grid-cols-2 md:items-start md:gap-x-4">
        <div>
          <section className="px-4 pt-8">
            <h2 className="font-display text-[1.5rem] leading-tight font-bold">Pickup</h2>
            <div className="mt-3 rounded-2xl bg-surface p-4">
              {/* Always set here: a counter sale has no customer status page. */}
              {order.pickupAt && (
                <p className="font-display text-[1.75rem] leading-none font-bold tabular-nums">
                  {formatDayLabel(order.pickupAt, tz)}, {formatTime(order.pickupAt, tz)}
                </p>
              )}
              <p className="mt-2 font-semibold">{location.name}</p>
              <p className="text-sm text-muted-foreground">
                {location.addressLine}, {location.city}{" "}
                {/* The one place directions matter most: they're walking to the truck now. */}
                <a
                  href={directionsUrl(location)}
                  target="_blank"
                  rel="noreferrer"
                  className="font-semibold text-foreground underline underline-offset-4 outline-none focus-visible:rounded-sm focus-visible:ring-3 focus-visible:ring-ring/50"
                >
                  Directions<span className="sr-only"> (opens in a new tab)</span>
                </a>
              </p>
              {location.notes && <p className="mt-1.5 text-sm text-muted-foreground">{location.notes}</p>}
            </div>
            {!cancelled && order.pickupAt && (
              <div className="mt-4">
                <OrderActions
                  orderId={order.id}
                  orderNumber={order.orderNumber}
                  truckName={truck.name}
                  pickupAt={order.pickupAt}
                  locationName={location.name}
                  address={`${location.addressLine}, ${location.city}`}
                />
              </div>
            )}
          </section>

          <section className="px-4 pt-8">
            <h2 className="font-display text-[1.5rem] leading-tight font-bold">Status</h2>
            {refresh && <RefreshStatus renderedAt={refresh.renderedAt} seconds={refresh.seconds} />}
            {cancelled ? (
              <p className="mt-3 rounded-2xl bg-surface p-4">
                This order was cancelled. If you were charged, you&apos;ll be refunded. Questions? Ask at the window.
              </p>
            ) : (
              <ol className="mt-3 rounded-2xl bg-surface p-4">
                {STEPS.map((step, i) => {
                  const done = i <= current;
                  return (
                    <li key={step.label} className="relative flex items-center gap-3 pb-5 last:pb-0">
                      {i < STEPS.length - 1 && (
                        <span
                          aria-hidden
                          className={cn("absolute top-7 bottom-0 left-[0.8125rem] w-0.5", i < current ? "bg-brand" : "bg-border")}
                        />
                      )}
                      <span
                        className={cn(
                          "relative z-10 flex size-7 shrink-0 items-center justify-center rounded-full text-xs font-bold",
                          done ? "bg-brand text-brand-foreground" : "bg-background text-muted-foreground ring-1 ring-border"
                        )}
                      >
                        {done ? <Check className="size-4" strokeWidth={3} /> : i + 1}
                      </span>
                      <span className={cn(done ? "font-semibold" : "text-muted-foreground")}>
                        {step.label}
                        {i === current ? (
                          <span className="sr-only"> (current step)</span>
                        ) : (
                          done && <span className="sr-only"> (done)</span>
                        )}
                      </span>
                    </li>
                  );
                })}
              </ol>
            )}
            {!cancelled && order.autoCompletedAt && (
              <p className="mt-3 text-sm text-muted-foreground">
                We closed this order automatically 30 minutes after it was ready. If you didn&apos;t collect it, ask at the window.
              </p>
            )}
          </section>

        </div>
        <div>
          <section className="px-4 pt-8">
            <h2 className="font-display text-[1.5rem] leading-tight font-bold">Receipt</h2>
            <div className="mt-3 rounded-2xl bg-surface p-4 text-[0.9375rem]">
              <ul className="divide-y divide-border">
                {order.lines.map((line) => (
                  <li key={line.id} className="flex justify-between gap-4 py-2.5 first:pt-0">
                    <div>
                      <p>
                        <span className="tabular-nums">{line.quantity}×</span> {line.name}
                      </p>
                      {line.modifiers.length > 0 && (
                        <p className="text-sm text-muted-foreground">{line.modifiers.join(", ")}</p>
                      )}
                    </div>
                    <p className="tabular-nums">{formatCents(line.lineTotalCents)}</p>
                  </li>
                ))}
              </ul>
              <dl className="mt-2 space-y-1.5 border-t border-border pt-3 tabular-nums">
                <ReceiptRow label="Subtotal" cents={order.subtotalCents} />
                <ReceiptRow label="Tax" cents={order.taxCents} />
                <ReceiptRow label="Tip" cents={order.tipCents} />
                <div className="flex justify-between pt-1 font-semibold">
                  <dt>Total</dt>
                  <dd>{formatCents(order.totalCents)}</dd>
                </div>
              </dl>
            </div>
          </section>

        </div>
      </div>

      <p className="px-4 pt-8">
        <Link href={`/${truck.slug}`} className="font-semibold text-brand underline underline-offset-4">
          Back to {truck.name}
        </Link>
      </p>
    </main>
  );
}

function ReceiptRow({ label, cents }: { label: string; cents: number }) {
  return (
    <div className="flex justify-between">
      <dt className="text-muted-foreground">{label}</dt>
      <dd>{formatCents(cents)}</dd>
    </div>
  );
}

// Vendor email notifications via Resend (resend.com). Without RESEND_API_KEY
// the email is printed to the terminal instead, so everything else still works.

import "server-only";
import { Resend } from "resend";
import type { OrderView, Truck } from "@/lib/types";
import { formatCents } from "@/lib/money";
import { formatWhen } from "@/lib/time";

const escapeHtml = (s: string) =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

export async function sendNewOrderEmail(input: {
  order: OrderView;
  truck: Truck;
  notificationEmail: string | null;
  locationName: string;
  notifyNewOrder?: boolean; // the vendor's per-event switch; absent = on
}): Promise<void> {
  const { order, truck, notificationEmail, locationName } = input;
  if (input.notifyNewOrder === false) return;
  if (!notificationEmail) {
    console.info(`[email] ${truck.name} has no notification email set; skipping order ${order.orderNumber}`);
    return;
  }

  const pickup = order.pickupAt ? formatWhen(order.pickupAt, truck.timezone) : "at the window"; // "today at 12:15 pm"
  const dashboardUrl = `${process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000"}/dashboard`;
  const subject = `New order ${order.orderNumber}: ${formatCents(order.totalCents)}, pickup ${pickup}`;

  const lineText = order.lines.map(
    (l) => `${l.quantity}× ${l.name}${l.modifiers.length ? ` (${l.modifiers.join(", ")})` : ""}  ${formatCents(l.lineTotalCents)}`
  );
  const text = [
    `Order ${order.orderNumber} for ${order.customerName} (${order.customerPhone})`,
    `Pickup ${pickup} at ${locationName}`,
    "",
    ...lineText,
    "",
    `Total ${formatCents(order.totalCents)} (includes ${formatCents(order.tipCents)} tip)`,
    "",
    `Open your order queue: ${dashboardUrl}`,
  ].join("\n");

  const html = `
    <div style="font-family:system-ui,sans-serif;max-width:480px;color:#1d2733">
      <p style="margin:0;color:#5c6660">${escapeHtml(truck.name)}</p>
      <h1 style="margin:4px 0 0;font-size:40px">${escapeHtml(order.orderNumber)}</h1>
      <p style="margin:8px 0 0"><strong>${escapeHtml(order.customerName)}</strong>${order.customerPhone ? ` · ${escapeHtml(order.customerPhone)}` : ""}</p>
      <p style="margin:4px 0 0">Pickup ${escapeHtml(pickup)} at ${escapeHtml(locationName)}</p>
      <table style="margin-top:16px;width:100%;border-collapse:collapse">
        ${order.lines
          .map(
            (l) => `<tr>
              <td style="padding:6px 0;border-top:1px solid #d9ddd6">${l.quantity}× ${escapeHtml(l.name)}${
                l.modifiers.length
                  ? `<br><span style="color:#5c6660;font-size:14px">${escapeHtml(l.modifiers.join(", "))}</span>`
                  : ""
              }</td>
              <td style="padding:6px 0;border-top:1px solid #d9ddd6;text-align:right">${formatCents(l.lineTotalCents)}</td>
            </tr>`
          )
          .join("")}
        <tr><td style="padding:8px 0;border-top:1px solid #d9ddd6"><strong>Total</strong></td>
            <td style="padding:8px 0;border-top:1px solid #d9ddd6;text-align:right"><strong>${formatCents(order.totalCents)}</strong></td></tr>
      </table>
      <p style="margin-top:20px"><a href="${dashboardUrl}" style="color:#1d2733">Open your order queue</a></p>
    </div>`;

  const apiKey = process.env.RESEND_API_KEY;
  if (!apiKey) {
    console.info(`[email] RESEND_API_KEY not set. Would send to ${notificationEmail}:\n  ${subject}\n${text.replace(/^/gm, "  ")}`);
    return;
  }

  const { error } = await new Resend(apiKey).emails.send({
    // Until you verify your own domain in Resend, you must send from its test address,
    // and it only delivers to the email you signed up to Resend with.
    from: process.env.EMAIL_FROM ?? "FoodtruckApp <onboarding@resend.dev>",
    to: notificationEmail,
    subject,
    text,
    html,
  });
  if (error) console.error("[email] Resend rejected the new-order email", error);
}

// ─── Settings emails ───────────────────────────────────────────────────────
// Unlike the new-order email, these report back: the vendor pressed a button
// and needs to know whether anything was actually sent.

export type SendResult = { sent: true } | { sent: false; reason: "not-configured" | "rejected"; error: string };

const FROM = () => process.env.EMAIL_FROM ?? "FoodtruckApp <onboarding@resend.dev>";

async function deliver(input: { to: string; subject: string; text: string; html: string }): Promise<SendResult> {
  const apiKey = process.env.RESEND_API_KEY;
  if (!apiKey) {
    console.info(`[email] RESEND_API_KEY not set. Would send to ${input.to}:\n  ${input.subject}\n${input.text.replace(/^/gm, "  ")}`);
    return { sent: false, reason: "not-configured", error: "Email isn't set up on this server (RESEND_API_KEY is missing)." };
  }
  try {
    const { error } = await new Resend(apiKey).emails.send({ from: FROM(), ...input });
    if (error) return { sent: false, reason: "rejected", error: error.message };
    return { sent: true };
  } catch (error) {
    return { sent: false, reason: "rejected", error: error instanceof Error ? error.message : "The email service couldn't be reached." };
  }
}

const appUrl = () => process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000";

export function sendTestEmail(input: { to: string; truckName: string }): Promise<SendResult> {
  const subject = `Test email from ${input.truckName}`;
  const text = `This is a test from FoodtruckApp. If you can read it, new-order emails for ${input.truckName} will reach this address.`;
  const html = `<div style="font-family:system-ui,sans-serif;max-width:480px;color:#1d2733">
    <p style="margin:0;color:#5c6660">${escapeHtml(input.truckName)}</p>
    <h1 style="margin:4px 0 0;font-size:24px">Your email works</h1>
    <p>New-order emails for ${escapeHtml(input.truckName)} will reach this address.</p></div>`;
  return deliver({ to: input.to, subject, text, html });
}

export function sendInviteEmail(input: { to: string; truckName: string; role: "OWNER" | "STAFF"; token: string; expiresAt: Date }): Promise<SendResult> {
  const link = `${appUrl()}/invite/${input.token}`;
  const roleText = input.role === "OWNER" ? "an owner" : "staff";
  const expires = input.expiresAt.toISOString().slice(0, 10);
  const subject = `You're invited to join ${input.truckName}`;
  const text = [
    `You've been invited to join ${input.truckName} on FoodtruckApp as ${roleText}.`,
    "",
    `Accept the invite: ${link}`,
    "",
    `The link works until ${expires} and only for you. If you weren't expecting this, ignore it.`,
  ].join("\n");
  const html = `<div style="font-family:system-ui,sans-serif;max-width:480px;color:#1d2733">
    <p style="margin:0;color:#5c6660">${escapeHtml(input.truckName)}</p>
    <h1 style="margin:4px 0 0;font-size:24px">You're invited</h1>
    <p>Join ${escapeHtml(input.truckName)} on FoodtruckApp as ${roleText}.</p>
    <p style="margin:20px 0"><a href="${link}" style="background:#1d2733;color:#fff;padding:12px 20px;border-radius:10px;text-decoration:none">Accept invite</a></p>
    <p style="color:#5c6660;font-size:14px">The link works until ${expires}. If you weren't expecting this, ignore it.</p></div>`;
  return deliver({ to: input.to, subject, text, html });
}

// Integer-cents math and formatting. Pure functions with no database access, so
// the client can use them to *display* an estimate. The authoritative totals
// are always recomputed on the server in lib/pricing.ts (Stream C).

import type { MenuItem } from "@/lib/types";

export function formatCents(cents: number): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(cents / 100);
}

/**
 * Parse what a vendor types into a price field ("12", "12.5", "$12.50") into
 * integer cents, using string math so there is no float rounding.
 * Returns null for anything that isn't a plain amount with at most 2 decimals.
 */
export function parseDollarsToCents(input: string): number | null {
  const match = input.trim().replace(/^\$/, "").replace(/,/g, "").match(/^(\d{1,6})(?:\.(\d{0,2}))?$/);
  if (!match) return null;
  const [, dollars, fraction = ""] = match;
  return Number(dollars) * 100 + Number(fraction.padEnd(2, "0"));
}

/** Cents → the plain string an input field shows, e.g. 1250 → "12.50". */
export function centsToInput(cents: number): string {
  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, "0")}`;
}

/** Apply a basis-point rate to an amount, rounding half up to the cent. */
export function applyBps(amountCents: number, bps: number): number {
  return Math.round((amountCents * bps) / 10_000);
}

export function unitPriceCents(item: MenuItem, optionIds: string[]): number {
  let cents = item.priceCents;
  for (const group of item.modifierGroups) {
    for (const option of group.options) {
      if (optionIds.includes(option.id)) cents += option.priceDeltaCents;
    }
  }
  return cents;
}

export function orderTotals(subtotalCents: number, taxRateBps: number, tipCents: number) {
  const taxCents = applyBps(subtotalCents, taxRateBps);
  return {
    subtotalCents,
    taxCents,
    tipCents,
    totalCents: subtotalCents + taxCents + tipCents,
  };
}

/**
 * Parse a percentage a vendor types ("8.25", "8.25%", "7") into basis points
 * (825, 825, 700) with string math, so there is no float rounding. At most two
 * decimals, since a basis point is 0.01%. Returns null for anything else.
 */
export function parsePercentToBps(input: string): number | null {
  const match = input.trim().replace(/%$/, "").trim().match(/^(\d{1,3})(?:\.(\d{0,2}))?$/);
  if (!match) return null;
  const [, whole, fraction = ""] = match;
  return Number(whole) * 100 + Number(fraction.padEnd(2, "0"));
}

/** Basis points → the plain string a percent input shows, e.g. 825 → "8.25", 700 → "7". */
export function bpsToPercentInput(bps: number): string {
  const whole = Math.floor(bps / 100);
  const fraction = String(bps % 100).padStart(2, "0").replace(/0+$/, "");
  return fraction ? `${whole}.${fraction}` : String(whole);
}

// What happens once an order is paid: mark it PAID and tell the vendor.
//
// TODO(Stream C): the Stripe webhook (checkout.session.completed) calls this.
// Until then, the checkout Server Action calls it right after createOrder,
// so orders are "paid" without a real payment.

import "server-only";
import { sendNewOrderEmail } from "@/lib/email";
import { getOrderNotification, setOrderPaid } from "@/lib/tenant";

export async function markOrderPaid(truckId: string, orderId: string): Promise<void> {
  const changed = await setOrderPaid(truckId, orderId);
  if (!changed) return; // already paid: Stripe retries webhooks, so this must be safe to repeat

  const notification = await getOrderNotification(truckId, orderId);
  if (!notification) return;

  // A failed email must never fail the order.
  try {
    await sendNewOrderEmail(notification);
  } catch (error) {
    console.error("[email] new-order email failed", error);
  }
}

// Server-side order pricing. The browser only sends item IDs, option IDs, and
// quantities; every price, total, and fee is recomputed here from menu rows
// loaded from the database. Pure function (no DB access) so it's easy to test.

import { applyBps } from "@/lib/money";

export type PricingOption = {
  id: string;
  name: string;
  priceDeltaCents: number;
  isAvailable: boolean;
};

export type PricingGroup = {
  id: string;
  name: string;
  minSelect: number;
  maxSelect: number;
  required: boolean;
  options: PricingOption[];
};

export type PricingItem = {
  id: string;
  name: string;
  priceCents: number;
  isAvailable: boolean;
  archivedAt: Date | null;
  modifierGroups: PricingGroup[];
};

export type RequestedLine = {
  menuItemId: string;
  optionIds: string[];
  quantity: number;
};

export type ModifierSnapshot = { group: string; name: string; priceDeltaCents: number };

export type PricedLine = {
  menuItemId: string;
  nameSnapshot: string;
  unitPriceCents: number;
  quantity: number;
  modifiersSnapshot: ModifierSnapshot[];
  lineTotalCents: number;
};

export type PricedOrder = {
  lines: PricedLine[];
  subtotalCents: number;
  taxCents: number;
  tipCents: number;
  platformFeeCents: number; // our cut, taken from the truck's payout, not added to the customer's total
  totalCents: number;
};

/** A problem the customer can fix (sold-out item, bad choice). The message is safe to show. */
export class PricingError extends Error {}

export const MAX_QUANTITY_PER_LINE = 20;
export const MAX_TIP_BPS = 5000; // 50%

export function priceOrder(input: {
  items: PricingItem[];
  lines: RequestedLine[];
  taxRateBps: number;
  tipBps: number;
  platformFeeBps: number;
}): PricedOrder {
  const { items, lines, taxRateBps, tipBps, platformFeeBps } = input;

  if (lines.length === 0) throw new PricingError("Your order is empty.");
  if (!Number.isInteger(tipBps) || tipBps < 0 || tipBps > MAX_TIP_BPS) {
    throw new PricingError("That tip amount isn't allowed.");
  }

  const byId = new Map(items.map((item) => [item.id, item]));

  const priced = lines.map((line): PricedLine => {
    const item = byId.get(line.menuItemId);
    if (!item || item.archivedAt) throw new PricingError("An item in your order is no longer on the menu.");
    if (!item.isAvailable) throw new PricingError(`${item.name} just sold out. Remove it to continue.`);
    if (!Number.isInteger(line.quantity) || line.quantity < 1 || line.quantity > MAX_QUANTITY_PER_LINE) {
      throw new PricingError(`Choose between 1 and ${MAX_QUANTITY_PER_LINE} of ${item.name}.`);
    }

    const chosen = new Set(line.optionIds);
    if (chosen.size !== line.optionIds.length) throw new PricingError(`Check your choices for ${item.name}.`);

    let unitPriceCents = item.priceCents;
    const modifiersSnapshot: ModifierSnapshot[] = [];
    let matched = 0;

    for (const group of item.modifierGroups) {
      const picks = group.options.filter((o) => chosen.has(o.id));
      matched += picks.length;

      const min = group.required ? Math.max(1, group.minSelect) : group.minSelect;
      if (picks.length < min) throw new PricingError(`Choose a ${group.name.toLowerCase()} for ${item.name}.`);
      if (picks.length > group.maxSelect) {
        throw new PricingError(`Choose at most ${group.maxSelect} ${group.name.toLowerCase()} for ${item.name}.`);
      }

      for (const option of picks) {
        if (!option.isAvailable) throw new PricingError(`${option.name} just sold out. Pick another option.`);
        unitPriceCents += option.priceDeltaCents;
        modifiersSnapshot.push({ group: group.name, name: option.name, priceDeltaCents: option.priceDeltaCents });
      }
    }

    // Any option ID that didn't belong to this item's groups is forged or stale.
    if (matched !== chosen.size) throw new PricingError(`Check your choices for ${item.name}.`);

    return {
      menuItemId: item.id,
      nameSnapshot: item.name,
      unitPriceCents,
      quantity: line.quantity,
      modifiersSnapshot,
      lineTotalCents: unitPriceCents * line.quantity,
    };
  });

  const subtotalCents = priced.reduce((sum, l) => sum + l.lineTotalCents, 0);
  const taxCents = applyBps(subtotalCents, taxRateBps);
  const tipCents = applyBps(subtotalCents, tipBps);

  return {
    lines: priced,
    subtotalCents,
    taxCents,
    tipCents,
    platformFeeCents: applyBps(subtotalCents, platformFeeBps),
    totalCents: subtotalCents + taxCents + tipCents,
  };
}

import { describe, expect, it } from "vitest";
import {
  SAVED_CUSTOMER_KEY,
  clearSavedCustomer,
  readSavedCustomer,
  writeSavedCustomer,
} from "@/lib/saved-customer";

function fakeStorage(initial: Record<string, string> = {}) {
  const data = new Map(Object.entries(initial));
  return {
    getItem: (k: string) => data.get(k) ?? null,
    setItem: (k: string, v: string) => void data.set(k, v),
    removeItem: (k: string) => void data.delete(k),
    data,
  };
}

const blocked = {
  getItem: () => {
    throw new Error("blocked");
  },
  setItem: () => {
    throw new Error("blocked");
  },
  removeItem: () => {
    throw new Error("blocked");
  },
};

describe("saved customer details", () => {
  it("saves and reads back the name and phone", () => {
    const storage = fakeStorage();
    expect(writeSavedCustomer(storage, { name: "Jo", phone: "262-555-0100" })).toBe(true);
    expect(readSavedCustomer(storage)).toEqual({ name: "Jo", phone: "262-555-0100" });
  });

  it("trims whitespace", () => {
    const storage = fakeStorage();
    writeSavedCustomer(storage, { name: "  Jo  ", phone: " 262 " });
    expect(readSavedCustomer(storage)).toEqual({ name: "Jo", phone: "262" });
  });

  it("returns null when nothing is saved", () => {
    expect(readSavedCustomer(fakeStorage())).toBeNull();
  });

  it("returns null for corrupt or wrongly shaped data", () => {
    for (const raw of ["not json", "null", "42", '{"name":1,"phone":"x"}', '{"name":"a"}', '{"name":"","phone":""}']) {
      expect(readSavedCustomer(fakeStorage({ [SAVED_CUSTOMER_KEY]: raw }))).toBeNull();
    }
  });

  it("caps very long values", () => {
    const storage = fakeStorage();
    writeSavedCustomer(storage, { name: "x".repeat(500), phone: "1".repeat(500) });
    const saved = readSavedCustomer(storage);
    expect(saved?.name.length).toBe(100);
    expect(saved?.phone.length).toBe(100);
  });

  it("clears the saved details", () => {
    const storage = fakeStorage();
    writeSavedCustomer(storage, { name: "Jo", phone: "262" });
    clearSavedCustomer(storage);
    expect(readSavedCustomer(storage)).toBeNull();
  });

  it("never throws when storage is blocked or missing", () => {
    expect(readSavedCustomer(blocked)).toBeNull();
    expect(writeSavedCustomer(blocked, { name: "Jo", phone: "262" })).toBe(false);
    expect(() => clearSavedCustomer(blocked)).not.toThrow();
    expect(readSavedCustomer(null)).toBeNull();
    expect(writeSavedCustomer(null, { name: "Jo", phone: "262" })).toBe(false);
    expect(() => clearSavedCustomer(undefined)).not.toThrow();
  });
});

// A stop's ordering window, from the two numbers the form asks for:
// "preorders open N hours before" (0 = right away) and "stop taking orders
// N minutes before the end". The defaults for both live on the Truck.

const HOUR = 60 * 60 * 1000;
const MINUTE = 60 * 1000;

export const MAX_OPENS_HOURS_BEFORE = 336; // two weeks
export const MAX_CLOSES_MINUTES_BEFORE = 1440;

type Input = {
  startsAt: Date;
  endsAt: Date;
  opensHoursBefore: number;
  closesMinutesBefore: number;
  now: Date;
  /** When editing: a stop that already opened keeps its opening time instead of resetting to now. */
  existingOpensAt?: Date;
};

export function resolveOrderingWindow(input: Input): { opensAt: Date; closesAt: Date } | { error: string } {
  const { startsAt, endsAt, opensHoursBefore, closesMinutesBefore, now, existingOpensAt } = input;

  const closesAt = new Date(endsAt.getTime() - closesMinutesBefore * MINUTE);
  const opensAt =
    opensHoursBefore === 0
      ? existingOpensAt && existingOpensAt <= now
        ? existingOpensAt
        : now
      : new Date(startsAt.getTime() - opensHoursBefore * HOUR);

  if (closesAt <= startsAt) return { error: "Ordering would close before the stop starts. Pick a shorter cut-off." };
  if (opensAt >= closesAt) return { error: "Ordering would close before it opens. Open it earlier, or close it later." };
  return { opensAt, closesAt };
}

/** The "opens N hours before" value to show when editing an existing stop. */
export function opensHoursBeforeOf(startsAt: Date, opensAt: Date): number {
  const hours = Math.round((startsAt.getTime() - opensAt.getTime()) / HOUR);
  return Math.min(MAX_OPENS_HOURS_BEFORE, Math.max(0, hours));
}

export function closesMinutesBeforeOf(endsAt: Date, closesAt: Date): number {
  const minutes = Math.round((endsAt.getTime() - closesAt.getTime()) / MINUTE);
  return Math.min(MAX_CLOSES_MINUTES_BEFORE, Math.max(0, minutes));
}

// Saves a stop and its pickup slots in one transaction. Pure orchestration over
// lib/tenant.ts. The rule that matters: a slot with orders is never deleted, so
// a save that would drop one is refused whole, before anything is written.

import { resolveOrderingWindow } from "@/lib/schedule/ordering-window";
import { MAX_SLOTS, bookedSlotMessage, generateSlots, planSlots } from "@/lib/schedule/slots";
import {
  createServiceWithSlots,
  getDefaultMenuIdForTruck,
  getServiceForEdit,
  getServiceSlots,
  replaceServiceSlots,
  serviceHasOrders,
  touchLocationUsed,
  updateServiceTimes,
  withTransaction,
} from "@/lib/tenant";

export type SaveServiceInput = {
  truckId: string;
  timeZone: string;
  serviceId?: string; // present = editing that stop
  locationId: string;
  startsAt: Date;
  endsAt: Date;
  opensHoursBefore: number;
  closesMinutesBefore: number;
  slotMinutes: number;
  ordersPerSlot: number;
  publicNote: string;
  publish: boolean;
  now: Date;
};

export type SaveServiceResult =
  | { ok: true; serviceId: string }
  | { ok: false; error: string; field?: "place" | "date" | "endTime" | "slots" };

const fail = (error: string, field?: "place" | "date" | "endTime" | "slots"): SaveServiceResult => ({ ok: false, error, field });

export function saveService(input: SaveServiceInput): Promise<SaveServiceResult> {
  const { truckId, timeZone, serviceId, locationId, startsAt, endsAt, slotMinutes, ordersPerSlot, now } = input;

  // Checked up front so a runaway range never builds a huge slot list.
  if (Math.ceil((endsAt.getTime() - startsAt.getTime()) / (slotMinutes * 60_000)) > MAX_SLOTS) {
    return Promise.resolve(fail("That is too many pickup times for one stop. Use longer slots or a shorter stop.", "slots"));
  }
  if (!serviceId && endsAt <= now) return Promise.resolve(fail("That stop is already over. Pick a later date.", "date"));

  return withTransaction(async (tx): Promise<SaveServiceResult> => {
    const existing = serviceId ? await getServiceForEdit(truckId, serviceId, tx) : null;
    if (serviceId) {
      if (!existing) return fail("That stop no longer exists.");
      if (existing.service.status === "CANCELLED") return fail("A cancelled stop can't be edited. Add a new stop instead.");
    }

    const window = resolveOrderingWindow({
      startsAt,
      endsAt,
      opensHoursBefore: input.opensHoursBefore,
      closesMinutesBefore: input.closesMinutesBefore,
      now,
      existingOpensAt: existing ? new Date(existing.service.orderingOpensAt) : undefined,
    });
    if ("error" in window) return fail(window.error);

    const locationChanged = !existing || existing.service.locationId !== locationId;
    // Orders read their pickup address from the stop's location and snapshot nothing.
    if (serviceId && locationChanged && (await serviceHasOrders(truckId, serviceId, tx))) {
      return fail("This stop already has orders, so its location can't change. Cancel it and add a new stop.", "place");
    }
    if (locationChanged && !(await touchLocationUsed(tx, truckId, locationId))) {
      return fail("That spot isn't available. Pick another.", "place");
    }

    const slots = generateSlots(startsAt, endsAt, slotMinutes, ordersPerSlot);
    const data = {
      locationId,
      startsAt,
      endsAt,
      orderingOpensAt: window.opensAt,
      orderingClosesAt: window.closesAt,
      slotMinutes,
      ordersPerSlot,
      publicNote: input.publicNote,
      status: existing && existing.service.status !== "DRAFT" ? existing.service.status : input.publish ? ("PUBLISHED" as const) : ("DRAFT" as const),
    };

    if (!existing) {
      const menuId = await getDefaultMenuIdForTruck(truckId);
      if (!menuId) return fail("Add a menu before scheduling a stop.");
      return { ok: true, serviceId: await createServiceWithSlots(tx, truckId, { ...data, menuId }, slots) };
    }

    // planSlots fills create/update/deleteIds even when it reports a conflict, so
    // the conflict is checked before any of the plan is used.
    const plan = planSlots(await getServiceSlots(tx, truckId, existing.service.id), slots);
    if (plan.conflict) return fail(bookedSlotMessage(plan.conflict, timeZone), "slots");

    if (!(await updateServiceTimes(tx, truckId, existing.service.id, data))) return fail("That stop can't be edited anymore.");
    if (!(await replaceServiceSlots(tx, truckId, existing.service.id, plan)).ok) {
      // An order landed on a slot being removed. Throwing rolls the transaction back.
      throw new SlotBookedError();
    }
    return { ok: true, serviceId: existing.service.id };
  }).catch((error) => {
    if (error instanceof SlotBookedError) return fail("An order just came in for one of the pickup times being removed. Try again.", "slots");
    throw error;
  });
}

class SlotBookedError extends Error {}

