/**
 * Storefront: the truck for a URL slug. (Custom domains resolve to a slug in middleware.)
 * A closed truck (archivedAt set) resolves to null, so every storefront page and
 * createOrder treat it as not found. The dashboard still reaches it via requireTruckAccess().
 */
export const getTruckFromRequest = cache(async (slug: string): Promise<Truck | null> => {
  const row = await prisma.truck.findUnique({ where: { slug } });
  return row && !row.archivedAt ? toTruck(row) : null;
});

export type TruckAccess = {
  userId: string;
  role: MembershipRole;
  truck: Truck;
  notificationEmail: string | null;
};

/**
 * Dashboard: the signed-in user's truck, via their Membership. Redirects to
 * sign-in or onboarding when there isn't one. Dashboard code must take its
 * truckId from here, never from a form field or URL. (With the dev login
 * bypass on, the "user" is the demo truck's owner: see lib/dev-auth.ts.)
 */
export const requireTruckAccess = cache(async (): Promise<TruckAccess> => {
  const userId = await getUserId();
  if (!userId) redirect("/sign-in");

  const findMembership = () =>
    prisma.membership.findFirst({
      where: { clerkUserId: userId },
      orderBy: { createdAt: "asc" },
      include: { truck: true },
    });
  let membership = await findMembership();
  // Dev login bypass: go straight to the demo truck instead of onboarding.
  if (!membership && DEV_AUTH_BYPASS && (await joinDemoTruck(userId, null))) membership = await findMembership();
  if (!membership) redirect("/dashboard/onboarding");

  return {
    userId,
    role: membership.role,
    truck: toTruck(membership.truck),
    notificationEmail: membership.truck.notificationEmail,
  };
});

